package com.afkrecap;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

// Retain the persisted group so existing settings survive the AFK Recap rename.
@ConfigGroup("away-recap")
public interface AfkRecapConfig extends Config
{
	@ConfigItem(keyName = "startOnFocusLoss", name = "Start on focus loss", description = "Start an away session when RuneLite loses focus", position = 0)
	default boolean startOnFocusLoss()
	{
		return true;
	}

	@ConfigItem(keyName = "startOnIdle", name = "Start on idle", description = "Start a candidate session after no mouse clicks or key presses", position = 1)
	default boolean startOnIdle()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(keyName = "idleGameTicks", name = "Idle game ticks", description = "Game ticks without manual input (approximately 600 ms per tick)", position = 2)
	default int idleGameTicks()
	{
		return 10;
	}

	@ConfigItem(keyName = "idleFishing", name = "Idle Fishing", description = "Fishing XP makes an idle session relevant", position = 3)
	default boolean idleFishing()
	{
		return true;
	}

	@ConfigItem(keyName = "idleMining", name = "Idle Mining", description = "Mining XP makes an idle session relevant", position = 4)
	default boolean idleMining()
	{
		return true;
	}

	@ConfigItem(keyName = "idleWoodcutting", name = "Idle Woodcutting", description = "Woodcutting XP makes an idle session relevant", position = 5)
	default boolean idleWoodcutting()
	{
		return true;
	}

	// Keep the legacy key: existing Sailing preferences now control Salvaging only.
	@ConfigItem(keyName = "idleSailing", name = "Idle Sailing Salvaging", description = "Gathering salvage makes an idle session relevant", position = 6)
	default boolean idleSailingSalvaging()
	{
		return true;
	}

	@ConfigItem(keyName = "idleSailingSorting", name = "Idle Sailing Sorting", description = "Sorting salvage makes an idle session relevant", position = 7)
	default boolean idleSailingSorting()
	{
		return false;
	}

	// Retain the former Slayer key so saved opt-outs carry over to Combat.
	@ConfigItem(keyName = "idleSlayer", name = "Idle Combat", description = "Attack, Strength, Defence, Ranged, Magic, or Hitpoints XP makes an idle session relevant", position = 8)
	default boolean idleCombat()
	{
		return true;
	}

	@ConfigItem(keyName = "idleSlayerActivity", name = "Idle Slayer", description = "Slayer XP makes an idle session relevant independently of Combat", position = 9)
	default boolean idleSlayer()
	{
		// RuneLite persists absent defaults when loading plugin/profile configuration.
		// Seed the split from the legacy combined preference once; saved values override this.
		return idleCombat();
	}

	@ConfigItem(keyName = "showOverlay", name = "Show recap overlay", description = "Show completed recaps in a temporary overlay; collection and debug logging continue when disabled", position = 10)
	default boolean showOverlay()
	{
		return true;
	}

	@Range(min = 3, max = 60)
	@ConfigItem(keyName = "overlayDurationSeconds", name = "Overlay duration", description = "Seconds to display each completed recap (applies to the next recap)", position = 11)
	default int overlayDurationSeconds()
	{
		return 10;
	}

	@ConfigItem(keyName = "enableSidePanel", name = "Enable side panel", description = "Show recent recaps in the sidebar; history continues collecting when disabled", position = 12)
	default boolean enableSidePanel()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(keyName = "recentRecapLimit", name = "Recent recap limit", description = "Maximum recent recaps retained in memory; reducing this trims history immediately", position = 13)
	default int recentRecapLimit()
	{
		return 20;
	}
	@ConfigItem(keyName = "trackNotableDrops", name = "Track notable drops", description = "Record notable ground drops owned by the local player during a session", position = 14)
	default boolean trackNotableDrops()
	{
		return true;
	}

	@Range(min = 0, max = Integer.MAX_VALUE)
	@ConfigItem(keyName = "notableDropValue", name = "Notable drop value", description = "Minimum approximate GE value of a newly spawned stack or stack addition", position = 15)
	default int notableDropValue()
	{
		return 100000;
	}

	@ConfigItem(keyName = "alwaysTrackClues", name = "Always track clues", description = "Include owned clue scroll drops regardless of value when notable-drop tracking is enabled", position = 16)
	default boolean alwaysTrackClues()
	{
		return true;
	}

	@ConfigItem(keyName = "trackMissedRandomEvents", name = "Track missed random events", description = "Record unhandled random events targeting you that disappear while away", position = 17)
	default boolean trackMissedRandomEvents()
	{
		return true;
	}

}

package com.afkrecap;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;

/** Presentation state shared by client events and overlay rendering; no game state mutations. */
@Singleton
public final class AfkRecapController
{
	private final LongSupplier nanoTime;
	private Presentation presentation;
	private long displayedAtNanos;
	private long displayDurationNanos;

	@Inject
	public AfkRecapController()
	{
		this(System::nanoTime);
	}

	AfkRecapController(LongSupplier nanoTime)
	{
		this.nanoTime = nanoTime;
	}

	synchronized void show(AfkRecapSession recap, boolean enabled, int durationSeconds)
	{
		show(recap, enabled, durationSeconds, AfkRecapItemPresentation.empty());
	}

	synchronized void show(AfkRecapSession recap, boolean enabled, int durationSeconds,
		AfkRecapItemPresentation.Display items)
	{
		if (!enabled || recap.getEndReason().isGameExit())
		{
			clear();
			return;
		}
		if (!recap.hasGains()
			|| (recap.getTrigger() == AfkSessionTrigger.IDLE && !recap.isIdleRelevant()))
		{
			return;
		}
		presentation = new Presentation(recap, items);
		displayedAtNanos = nanoTime.getAsLong();
		displayDurationNanos = TimeUnit.SECONDS.toNanos(Math.max(3, Math.min(60, durationSeconds)));
	}

	synchronized Presentation visiblePresentation(boolean enabled)
	{
		if (!enabled || (presentation != null
			&& nanoTime.getAsLong() - displayedAtNanos >= displayDurationNanos))
		{
			clear();
		}
		return presentation;
	}

	synchronized void clear()
	{
		presentation = null;
	}

	static String formatDuration(long elapsedMillis)
	{
		if (elapsedMillis < 60_000)
		{
			return String.format(Locale.ROOT, "%.1fs", elapsedMillis / 1000.0);
		}
		long seconds = elapsedMillis / 1000;
		return seconds / 60 + "m " + seconds % 60 + "s";
	}

	@Getter
	static final class Presentation
	{
		private final String duration;
		private final String trigger;
		private final List<XpRow> xpRows;
		private final List<AfkRecapItemPresentation.ItemRow> itemRows;
		private final List<AfkRecapItemPresentation.ItemRow> notableDropRows;
		private final String totalValue;
		private final Map<String, Integer> npcKills;
		private final Map<String, Integer> missedRandomEvents;
		private final String prayerUsed;
		private final String damageTaken;

		private Presentation(AfkRecapSession recap, AfkRecapItemPresentation.Display items)
		{
			damageTaken = recap.getDamageTaken() > 0 ? Long.toString(recap.getDamageTaken()) : null;
			npcKills = recap.getNpcKills();
			missedRandomEvents = recap.getMissedRandomEvents();
			prayerUsed = recap.getPrayerUsed() > 0 ? Long.toString(recap.getPrayerUsed()) : null;
			itemRows = items.getRows();
			notableDropRows = items.getNotableRows();
			totalValue = items.getTotalValue();
			duration = formatDuration(recap.getElapsedMillis());
			trigger = recap.getTrigger() == AfkSessionTrigger.FOCUS ? "Focus" : "Idle";
			List<XpRow> rows = new ArrayList<>();
			recap.getXpGained().forEach((skill, gained) ->
			{
				if (gained > 0)
				{
					rows.add(new XpRow(skill.getName(), "+" + gained + " XP"));
				}
			});
			xpRows = Collections.unmodifiableList(rows);
		}
	}

	@Getter
	static final class XpRow
	{
		private final String skill;
		private final String gained;

		private XpRow(String skill, String gained)
		{
			this.skill = skill;
			this.gained = gained;
		}
	}
}

package com.afkrecap;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import javax.inject.Singleton;

/** Bounded, in-memory completed recap history, independent of panel visibility and Swing. */
@Singleton
public final class AfkRecapHistory
{
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private int limit = 20;

	synchronized boolean add(AfkRecapSession recap)
	{
		if (!recap.hasGains()
			|| (recap.getTrigger() == AfkSessionTrigger.IDLE && !recap.isIdleRelevant()))
		{
			return false;
		}
		recaps.add(0, recap);
		// Stable sort keeps the newest arrival first when completion timestamps tie.
		recaps.sort(Comparator.comparing(AfkRecapSession::getEndTimestamp).reversed());
		trim();
		return true;
	}

	synchronized void setLimit(int limit)
	{
		this.limit = Math.max(1, Math.min(100, limit));
		trim();
	}

	synchronized List<AfkRecapSession> snapshot()
	{
		return Collections.unmodifiableList(new ArrayList<>(recaps));
	}

	synchronized void clear()
	{
		recaps.clear();
	}

	private void trim()
	{
		if (recaps.size() > limit)
		{
			recaps.subList(limit, recaps.size()).clear();
		}
	}
}

package com.afkrecap;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.WeakHashMap;
import java.util.function.IntFunction;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/** Resolve on the client thread once; UI code only reads immutable cached presentation data. */
@Singleton
@Slf4j
public final class AfkRecapItemPresentation
{
	private static final Display EMPTY = new Display(Collections.emptyList(), null, Collections.emptyList());
	private final IntFunction<ItemDetails> lookup;
	// Values never reference the key: presentations live only as long as history/overlay need them.
	private final Map<AfkRecapSession, Display> cache = new WeakHashMap<>();

	@Inject
	AfkRecapItemPresentation(ItemManager itemManager)
	{
		this(id ->
		{
			ItemComposition definition = itemManager.getItemComposition(id);
			String name = definition == null ? null : definition.getName();
			if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
			{
				return new ItemDetails(null, 0);
			}
			long price = 0;
			try
			{
				price = itemManager.getItemPrice(id);
			}
			catch (RuntimeException exception)
			{
				log.debug("Unable to price recap item {}", id, exception);
			}
			return new ItemDetails(name, price);
		});
	}

	AfkRecapItemPresentation(IntFunction<ItemDetails> lookup)
	{
		this.lookup = lookup;
	}

	synchronized Display prepare(AfkRecapSession recap)
	{
		if (recap.getItemGains().isEmpty() && recap.getNotableDrops().isEmpty())
		{
			return EMPTY;
		}
		Display cached = cache.get(recap);
		if (cached != null)
		{
			return cached;
		}
		Display items = format(recap.getItemGains());
		Display drops = format(recap.getNotableDrops());
		Display display = new Display(items.rows, items.totalValue, drops.rows);
		cache.put(recap, display);
		return display;
	}

	private Display format(Map<Integer, Integer> gains)
	{
		List<ItemRow> rows = new ArrayList<>();
		BigInteger total = BigInteger.ZERO;
		boolean priced = false;
		for (Map.Entry<Integer, Integer> entry : gains.entrySet())
		{
			int id = entry.getKey();
			ItemDetails details;
			try
			{
				details = lookup.apply(id);
			}
			catch (RuntimeException exception)
			{
				log.debug("Unable to resolve recap item {}", id, exception);
				details = null;
			}
			String name = details == null ? null : details.name;
			if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
			{
				name = "Item " + id;
			}
			String value = null;
			if (details != null && details.unitPrice > 0)
			{
				BigInteger itemValue = BigInteger.valueOf(details.unitPrice)
					.multiply(BigInteger.valueOf(entry.getValue()));
				total = total.add(itemValue);
				value = gp(itemValue);
				priced = true;
			}
			rows.add(new ItemRow(name, String.format(Locale.US, "%,d", entry.getValue()), value));
		}
		return new Display(rows, priced ? gp(total) : null, Collections.emptyList());
	}

	synchronized Display get(AfkRecapSession recap)
	{
		return cache.getOrDefault(recap, EMPTY);
	}

	static Display empty()
	{
		return EMPTY;
	}

	private static String gp(BigInteger value)
	{
		return String.format(Locale.US, "%,d gp", value);
	}

	static final class ItemDetails
	{
		private final String name;
		private final long unitPrice;

		ItemDetails(String name, long unitPrice)
		{
			this.name = name;
			this.unitPrice = unitPrice;
		}
	}

	@Getter
	static final class Display
	{
		private final List<ItemRow> rows;
		private final String totalValue;
		private final List<ItemRow> notableRows;

		private Display(List<ItemRow> rows, String totalValue, List<ItemRow> notableRows)
		{
			this.rows = Collections.unmodifiableList(new ArrayList<>(rows));
			this.totalValue = totalValue;
			this.notableRows = Collections.unmodifiableList(new ArrayList<>(notableRows));
		}
	}

	@Getter
	static final class ItemRow
	{
		private final String name;
		private final String quantity;
		private final String value;
		private final String quantityAndValue;

		private ItemRow(String name, String quantity, String value)
		{
			this.name = name;
			this.quantity = quantity;
			this.value = value;
			this.quantityAndValue = quantity + (value == null ? "" : "  " + value);
		}
	}
}

package com.afkrecap;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Singleton
public final class AfkRecapOverlay extends OverlayPanel
{
	// Reserve one row for a history hint; never discard collected recap data.
	static final int MAX_ROWS = 24;
	private final AfkRecapConfig config;
	private final AfkRecapController controller;

	@Inject
	AfkRecapOverlay(AfkRecapPlugin plugin, AfkRecapConfig config, AfkRecapController controller)
	{
		super(plugin);
		this.config = config;
		this.controller = controller;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(220, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		AfkRecapController.Presentation recap = controller.visiblePresentation(config.showOverlay());
		if (recap == null)
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("AFK Recap").color(Color.YELLOW).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Away:").right(recap.getDuration()).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Trigger:").right(recap.getTrigger()).build());
		if (!recap.getXpRows().isEmpty() && hasRowSpace())
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("XP gained").build());
		}
		for (AfkRecapController.XpRow row : recap.getXpRows())
		{
			if (!hasRowSpace())
			{
				break;
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left(row.getSkill()).right(row.getGained()).build());
		}
		if (!recap.getMissedRandomEvents().isEmpty() && hasRowSpace())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Missed random events").build());
			for (Map.Entry<String, Integer> entry : recap.getMissedRandomEvents().entrySet())
			{
				if (!hasRowSpace())
				{
					break;
				}
				panelComponent.getChildren().add(LineComponent.builder()
					.left(entry.getKey()).right(entry.getValue().toString()).build());
			}
		}

		if (!recap.getNpcKills().isEmpty() && hasRowSpace())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Kills").build());
			for (Map.Entry<String, Integer> entry : recap.getNpcKills().entrySet())
			{
				if (!hasRowSpace())
				{
					break;
				}
				panelComponent.getChildren().add(LineComponent.builder()
					.left(entry.getKey()).right(entry.getValue().toString()).build());
			}
		}
		if (recap.getPrayerUsed() != null && hasRowSpace())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Prayer used:").right(recap.getPrayerUsed()).build());
		}

		if (recap.getDamageTaken() != null && hasRowSpace())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Damage taken:").right(recap.getDamageTaken()).build());
		}

		if (!recap.getNotableDropRows().isEmpty() && hasRowSpace())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Notable drops").build());
			for (AfkRecapItemPresentation.ItemRow row : recap.getNotableDropRows())
			{
				if (!hasRowSpace())
				{
					break;
				}
				panelComponent.getChildren().add(LineComponent.builder()
					.left(row.getName()).right(row.getQuantityAndValue()).build());
			}
		}

		if (!recap.getItemRows().isEmpty() && hasRowSpace())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Items gained").build());
			for (AfkRecapItemPresentation.ItemRow row : recap.getItemRows())
			{
				if (!hasRowSpace())
				{
					break;
				}
				panelComponent.getChildren().add(LineComponent.builder()
					.left(row.getName()).right(row.getQuantityAndValue()).build());
			}
			if (recap.getTotalValue() != null && hasRowSpace())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Total value:").right(recap.getTotalValue()).build());
			}
		}
		int totalRows = 3 + sectionRows(recap.getXpRows().size())
			+ sectionRows(recap.getMissedRandomEvents().size()) + sectionRows(recap.getNpcKills().size())
			+ sectionRows(recap.getNotableDropRows().size()) + sectionRows(recap.getItemRows().size())
			+ (recap.getPrayerUsed() == null ? 0 : 1) + (recap.getDamageTaken() == null ? 0 : 1)
			+ (recap.getItemRows().isEmpty() || recap.getTotalValue() == null ? 0 : 1);
		if (totalRows > panelComponent.getChildren().size())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("More details in history").build());
		}
		return super.render(graphics);
	}
	private boolean hasRowSpace()
	{
		return panelComponent.getChildren().size() < MAX_ROWS - 1;
	}

	private static int sectionRows(int size)
	{
		return size == 0 ? 0 : size + 1;
	}

}

package com.afkrecap;

import java.awt.BorderLayout;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.ZoneId;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;

public final class AfkRecapPanel extends PluginPanel
{
	private final AfkRecapHistory history;
	private final AfkRecapItemPresentation itemPresentation;
	private final JPanel entries = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JButton clearHistory = new JButton("Clear History");

	AfkRecapPanel(AfkRecapHistory history, AfkRecapItemPresentation itemPresentation)
	{
		this.history = history;
		this.itemPresentation = itemPresentation;
		setLayout(new BorderLayout(0, 8));
		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		JLabel title = new JLabel("AFK Recap");
		title.setForeground(ColorScheme.BRAND_ORANGE);
		header.add(title, BorderLayout.NORTH);
		header.add(clearHistory, BorderLayout.SOUTH);
		clearHistory.addActionListener(event ->
		{
			history.clear();
			refresh();
		});
		entries.setOpaque(false);
		add(header, BorderLayout.NORTH);
		add(entries, BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		assert SwingUtilities.isEventDispatchThread();
		List<AfkRecapSession> recaps = history.snapshot();
		entries.removeAll();
		clearHistory.setEnabled(!recaps.isEmpty());
		if (recaps.isEmpty())
		{
			JLabel empty = new JLabel("No completed recaps yet.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			entries.add(empty);
		}
		else
		{
			for (AfkRecapSession recap : recaps)
			{
				entries.add(entry(recap));
			}
		}
		entries.revalidate();
		entries.repaint();
	}

	private JPanel entry(AfkRecapSession recap)
	{
		JPanel card = new JPanel(new BorderLayout(0, 5));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		JLabel heading = new JLabel(AfkRecapPanelPresentation.header(recap, ZoneId.systemDefault()));
		heading.setForeground(ColorScheme.TEXT_COLOR);
		card.add(heading, BorderLayout.NORTH);
		JPanel xpRows = new JPanel(new GridLayout(0, 1, 0, 2));
		xpRows.setOpaque(false);
		recap.getXpGained().forEach((skill, gained) ->
		{
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setOpaque(false);
			row.add(new JLabel(skill.getName()), BorderLayout.WEST);
			row.add(new JLabel(AfkRecapPanelPresentation.xp(gained)), BorderLayout.EAST);
			xpRows.add(row);
		});
		if (!recap.getMissedRandomEvents().isEmpty())
		{
			xpRows.add(new JLabel("Missed random events"));
			recap.getMissedRandomEvents().forEach((name, count) ->
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setOpaque(false);
				row.add(new JLabel(name), BorderLayout.CENTER);
				row.add(new JLabel(count.toString()), BorderLayout.EAST);
				xpRows.add(row);
			});
		}

		if (!recap.getNpcKills().isEmpty())
		{
			xpRows.add(new JLabel("Kills"));
			recap.getNpcKills().forEach((name, count) ->
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setOpaque(false);
				row.add(new JLabel(name), BorderLayout.CENTER);
				row.add(new JLabel(count.toString()), BorderLayout.EAST);
				xpRows.add(row);
			});
		}
		if (recap.getPrayerUsed() > 0)
		{
			xpRows.add(new JLabel("Prayer used: " + recap.getPrayerUsed()));
		}

		if (recap.getDamageTaken() > 0)
		{
			xpRows.add(new JLabel("Damage taken: " + recap.getDamageTaken()));
		}

		AfkRecapItemPresentation.Display items = itemPresentation.get(recap);
		if (!items.getNotableRows().isEmpty())
		{
			xpRows.add(new JLabel("Notable drops"));
			for (AfkRecapItemPresentation.ItemRow item : items.getNotableRows())
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setOpaque(false);
				row.add(new JLabel(item.getName()), BorderLayout.CENTER);
				row.add(new JLabel(item.getQuantityAndValue()), BorderLayout.EAST);
				xpRows.add(row);
			}
		}

		if (!items.getRows().isEmpty())
		{
			JLabel itemHeading = new JLabel("Items gained");
			itemHeading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			xpRows.add(itemHeading);
			for (AfkRecapItemPresentation.ItemRow item : items.getRows())
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setOpaque(false);
				JLabel name = new JLabel(item.getName());
				name.setToolTipText(item.getName());
				row.add(name, BorderLayout.CENTER);
				row.add(new JLabel(item.getQuantityAndValue()), BorderLayout.EAST);
				xpRows.add(row);
			}
			if (items.getTotalValue() != null)
			{
				JPanel total = new JPanel(new BorderLayout(6, 0));
				total.setOpaque(false);
				total.add(new JLabel("Total value:"), BorderLayout.WEST);
				total.add(new JLabel(items.getTotalValue()), BorderLayout.EAST);
				xpRows.add(total);
			}
		}
		card.add(xpRows, BorderLayout.CENTER);
		return card;
	}

	static BufferedImage navigationIcon()
	{
		// Small code-drawn clock icon; no file I/O or large raster asset.
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(ColorScheme.BRAND_ORANGE);
			graphics.drawOval(1, 1, 13, 13);
			graphics.drawLine(8, 4, 8, 8);
			graphics.drawLine(8, 8, 11, 10);
		}
		finally
		{
			graphics.dispose();
		}
		return icon;
	}
}

package com.afkrecap;

import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

final class AfkRecapPanelPresentation
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm");

	private AfkRecapPanelPresentation()
	{
	}

	static String header(AfkRecapSession recap, ZoneId zone)
	{
		String trigger = recap.getTrigger() == AfkSessionTrigger.FOCUS ? "Focus" : "Idle";
		long seconds = recap.getElapsedMillis() / 1000;
		String duration = seconds < 60 ? AfkRecapController.formatDuration(recap.getElapsedMillis())
			: String.format(Locale.ROOT, "%dm %02ds", seconds / 60, seconds % 60);
		return TIME.format(recap.getEndTimestamp().atZone(zone)) + " — " + trigger + " — " + duration;
	}

	static String xp(long gained)
	{
		return String.format(Locale.US, "+%,d XP", gained);
	}
}

