@Slf4j
@PluginDescriptor(
	name = "AFK Recap",
	description = "Tracks what happens while you are AFK or away from RuneLite and summarizes XP, items, combat activity, and other session data when you return."
)
public class AfkRecapPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AfkRecapConfig config;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AfkRecapOverlay overlay;

	@Inject
	private AfkRecapController recapController;

	@Inject
	private AfkRecapHistory recapHistory;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private AfkRecapItemPresentation itemPresentation;

	@Inject
	private ItemManager itemManager;

	// Panel and navigation state are accessed only on the Swing EDT.
	private AfkRecapPanel sidePanel;
	private NavigationButton navigationButton;
	private boolean navigationAdded;

	private volatile Object recapLifecycle;

	// Input callbacks are on the AWT thread; state mutations are queued on the client thread.
	private volatile AfkSessionManager sessions;

	private final MouseAdapter mouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			manualInput();
			return event;
		}
	};

	private final KeyListener keyListener = new KeyListener()
	{
		@Override
		public void keyPressed(KeyEvent event)
		{
			manualInput();
		}

		@Override
		public void keyReleased(KeyEvent event)
		{
		}

		@Override
		public void keyTyped(KeyEvent event)
		{
		}
	};

	@Provides
	AfkRecapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AfkRecapConfig.class);
	}

	@Override
	protected void startUp()
	{
		Object lifecycle = new Object();
		recapLifecycle = lifecycle;
		recapController.clear();
		recapHistory.setLimit(config.recentRecapLimit());
		AfkSessionManager started = new AfkSessionManager(System::nanoTime, Instant::now, recap ->
		{
			if (recapLifecycle == lifecycle)
			{
				recapHistory.add(recap);
				AfkRecapItemPresentation.Display items = itemPresentation.prepare(recap);
				recapController.show(recap, config.showOverlay(), config.overlayDurationSeconds(), items);
				refreshSidePanel();
			}
		}, this::inventorySnapshot);
		started.suspend();
		sessions = started;
		clientThread.invoke(() ->
		{
			if (sessions == started && client.getGameState() == GameState.LOGGED_IN)
			{
				baselineExperience(started);
			}
		});
		mouseManager.registerMouseListener(mouseListener);
		keyManager.registerKeyListener(keyListener);
		overlayManager.add(overlay);
		updateSidePanel();
	}

	@Override
	protected void shutDown()
	{
		recapLifecycle = null;
		updateSidePanel();
		overlayManager.remove(overlay);
		recapController.clear();
		AfkSessionManager stopped = sessions;
		sessions = null;
		mouseManager.unregisterMouseListener(mouseListener);
		keyManager.unregisterKeyListener(keyListener);
		if (stopped != null)
		{
			clientThread.invoke(stopped::suspend);
		}
	}

	private void manualInput()
	{
		AfkSessionManager current = sessions;
		if (current != null)
		{
			clientThread.invoke(() ->
			{
				// Ignore callbacks belonging to a previous enable/disable cycle.
				if (sessions == current && client.getGameState() == GameState.LOGGED_IN)
				{
					current.configureRandomEvents(config.trackMissedRandomEvents());
					current.manualInput();
				}
			});
		}
	}

	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		log.debug("RuneLite {} focus", event.isFocused() ? "gained" : "lost");
		AfkSessionManager current = sessions;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			current.configureRandomEvents(config.trackMissedRandomEvents());
			current.focusChanged(event.isFocused(), config);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		AfkSessionManager current = sessions;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			if (!current.isReady())
			{
				// All login stat synchronization has been processed before this tick.
				current.loggedIn(experienceSnapshot(), client.getBoostedSkillLevel(Skill.PRAYER));
				return;
			}
			current.gameTick(config);
			if (current.trigger() == AfkSessionTrigger.IDLE && client.getLocalPlayer() != null)
			{
				current.activityDetected(SailingActivitySignals.animation(client.getLocalPlayer().getAnimation()));
			}
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() == AfkSessionTrigger.IDLE && current.isReady()
			&& client.getGameState() == GameState.LOGGED_IN && event.getActor() != null && event.getActor() == client.getLocalPlayer())
		{
			current.activityDetected(SailingActivitySignals.animation(event.getActor().getAnimation()));
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		AfkSessionManager current = sessions;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			current.statChanged(event.getSkill(), event.getXp());
			if (event.getSkill() == Skill.PRAYER)
			{
				current.prayerChanged(event.getBoostedLevel());
			}
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null && client.getGameState() == GameState.LOGGED_IN)
		{
			Hitsplat hit = event.getHitsplat();
			if (event.getActor() != null && event.getActor() == client.getLocalPlayer())
			{
				current.playerHitsplat(hit);
			}
			else if (event.getActor() instanceof NPC && hit != null)
			{
				current.npcDamage(event.getActor(), hit.getAmount(), hit.isMine(), hit.isOthers());
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null && client.getGameState() == GameState.LOGGED_IN
			&& event.getActor() instanceof NPC)
		{
			current.npcDeath(event.getActor(), event.getActor().getName());
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		AfkSessionManager current = sessions;
		if (current == null || !current.isReady() || current.trigger() == null
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		current.configureRandomEvents(config.trackMissedRandomEvents());
		if (!config.trackMissedRandomEvents() || client.getLocalPlayer() == null)
		{
			return;
		}
		if (event.getSource() == client.getLocalPlayer())
		{
			current.randomEventHandled(event.getTarget());
		}
		else if (event.getSource() instanceof NPC)
		{
			NPC npc = (NPC) event.getSource();
			// Ownership predicate adapted from RuneLite RandomEventPlugin; see META-INF/NOTICE.
			if (event.getTarget() == client.getLocalPlayer() && RandomEventTypes.contains(npc.getId()))
			{
				current.randomEventTargeted(npc, npc.getId(), npc.getName(), true,
					client.getLocalPlayer().getInteracting() == npc);
			}
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null)
		{
			current.npcDespawned(event.getNpc());
			current.configureRandomEvents(config.trackMissedRandomEvents());
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				current.randomEventDespawned(event.getNpc());
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null && client.getGameState() == GameState.LOGGED_IN
			&& event.getContainerId() == InventoryID.INV)
		{
			ItemContainer inventory = event.getItemContainer();
			current.inventoryChanged(inventory == null ? null : InventoryGainTracker.totals(inventory.getItems()));
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		trackGroundItem(event.getItem(), -1, event.getItem() == null ? 0 : event.getItem().getQuantity());
	}

	@Subscribe
	public void onItemQuantityChanged(ItemQuantityChanged event)
	{
		trackGroundItem(event.getItem(), event.getOldQuantity(), event.getNewQuantity());
	}

	private void trackGroundItem(TileItem item, int oldQuantity, int quantity)
	{
		AfkSessionManager current = sessions;
		if (current == null || current.trigger() == null || !current.isReady()
			|| client.getGameState() != GameState.LOGGED_IN || !config.trackNotableDrops()
			|| item == null || quantity < 0 || item.getId() < 0
			|| !NotableDropTracker.attributed(item.getOwnership()))
		{
			return;
		}
		if (oldQuantity >= 0 && quantity <= oldQuantity)
		{
			current.groundQuantityChanged(item, item.getId(), oldQuantity, quantity, item.getOwnership(), 0, false, config);
			return;
		}
		try
		{
			int id = item.getId();
			ItemComposition definition = itemManager.getItemComposition(id);
			if (definition == null)
			{
				return;
			}
			boolean clue = ClueDropItems.isClue(id, definition.getIntValue(ParamID.CLUE_SCROLL));
			long price = -1;
			try
			{
				price = itemManager.getItemPrice(id);
			}
			catch (RuntimeException exception)
			{
				log.debug("Unable to price notable ground item {}", id, exception);
			}
			if (oldQuantity < 0)
			{
				current.groundSpawn(item, id, quantity, item.getOwnership(), price, clue, config);
			}
			else
			{
				current.groundQuantityChanged(item, id, oldQuantity, quantity, item.getOwnership(), price, clue, config);
			}
		}
		catch (RuntimeException exception)
		{
			log.debug("Unable to resolve notable ground item {}", item.getId(), exception);
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null)
		{
			current.groundDespawn(event.getItem());
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		AfkSessionManager current = sessions;
		if (current == null || current.trigger() == null || client.getGameState() != GameState.LOGGED_IN || !current.isReady())
		{
			return;
		}
		if (!ResourceAcquisitionMessages.acceptsChat(Family.LOG, event.getType()) || event.getMessage() == null)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (current.trigger() == AfkSessionTrigger.IDLE)
		{
			current.activityDetected(SailingActivitySignals.message(message));
		}
		if (event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			switch (message)
			{
				case "You empty your basket.":
				case "You empty as many logs as you can carry.":
				case "You empty your basket into the bank.":
					current.resourceTransfer(Family.LOG);
					break;
				case "You empty all of your containers into the bank.":
					current.resourceTransfer(Family.FISH);
					current.resourceTransfer(Family.LOG);
					break;
				default:
					break;
			}
		}
		if (!ResourceAcquisitionMessages.mayAcquire(message))
		{
			// Preserve bonus-context invalidation without inspecting inventory/equipment.
			current.acquisitionMessage(message, false, false);
			return;
		}
		ResourceContainerState storage = resourceContainerState();
		current.acquisitionMessage(message,
			ResourceAcquisitionMessages.acceptsChat(Family.FISH, event.getType()) && storage.hiddenFish(),
			storage.hiddenLogs());
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		AfkSessionManager current = sessions;
		if (current == null || current.trigger() == null || client.getGameState() != GameState.LOGGED_IN || !current.isReady())
		{
			return;
		}
		if (event.getMenuOption() == null || event.getMenuAction() == null)
		{
			return;
		}
		String option = Text.removeTags(event.getMenuOption()).toLowerCase(Locale.ROOT);
		current.configureRandomEvents(config.trackMissedRandomEvents());
		if (!event.isConsumed() && (option.equals("talk-to") || option.equals("dismiss"))
			&& event.getMenuAction().getId() >= MenuAction.NPC_FIRST_OPTION.getId()
			&& event.getMenuAction().getId() <= MenuAction.NPC_FIFTH_OPTION.getId())
		{
			current.randomEventHandled(event.getMenuEntry().getNpc());
		}
		Widget widget = event.getWidget();
		Family container = widget == null ? null : ResourceAcquisitionMessages.container(widget.getItemId());
		if (container == null)
		{
			container = ResourceAcquisitionMessages.container(event.getItemId());
		}
		// Item-on-container and container-on-bank-stand transfers have different target widgets.
		switch (event.getMenuAction())
		{
			case WIDGET_TARGET_ON_WIDGET:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_NPC:
				Widget selected = client.getSelectedWidget();
				Family selectedContainer = selected == null ? null
					: ResourceAcquisitionMessages.container(selected.getItemId());
				if (container != null || selectedContainer != null)
				{
					current.resourceTransfer(container != null ? container : selectedContainer);
				}
				return;
			default:
				break;
		}
		if (container != null && (option.equals("fill") || option.startsWith("empty")))
		{
			current.resourceTransfer(container);
		}
		else if (widget != null && (option.startsWith("withdraw") || option.startsWith("deposit")
			|| option.equals("empty basket")))
		{
			// Bank buttons and the forestry equipment interface may not carry an item ID.
			ResourceContainerState storage = resourceContainerState();
			for (Family family : Family.values())
			{
				if (storage.hasContainer(family))
				{
					current.resourceTransfer(family);
				}
			}
		}
		// Check dialogs are intentionally not subscribed to: their contents are synchronization.
	}

	private ResourceContainerState resourceContainerState()
	{
		Set<Integer> items = new HashSet<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container != null)
			{
				for (Item item : container.getItems())
				{
					if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
					{
						items.add(item.getId());
					}
				}
			}
		}
		return new ResourceContainerState(items);
	}

	private Map<Integer, Integer> inventorySnapshot()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory == null ? null : InventoryGainTracker.totals(inventory.getItems());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			// An earlier return overlay must not remain on the login/reconnect screen either.
			recapController.clear();
		}
		AfkSessionManager current = sessions;
		if (current != null)
		{
			current.configureRandomEvents(config.trackMissedRandomEvents());
			current.gameStateChanged(event.getGameState());
			if (event.getGameState() == GameState.LOGGED_IN)
			{
				baselineExperience(current);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("away-recap".equals(event.getGroup()) && "showOverlay".equals(event.getKey())
			&& !config.showOverlay())
		{
			recapController.clear();
		}
		if ("away-recap".equals(event.getGroup()))
		{
			if ("trackMissedRandomEvents".equals(event.getKey()))
			{
				clientThread.invoke(() ->
				{
					if (sessions != null)
					{
						sessions.configureRandomEvents(config.trackMissedRandomEvents());
					}
				});
			}
			else if ("recentRecapLimit".equals(event.getKey()))
			{
				recapHistory.setLimit(config.recentRecapLimit());
				refreshSidePanel();
			}
			else if ("enableSidePanel".equals(event.getKey()))
			{
				updateSidePanel();
			}
		}
	}

	private void refreshSidePanel()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (recapLifecycle != null && config.enableSidePanel() && sidePanel != null)
			{
				sidePanel.refresh();
			}
		});
	}

	private void updateSidePanel()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (recapLifecycle == null || !config.enableSidePanel())
			{
				if (navigationAdded)
				{
					clientToolbar.removeNavigation(navigationButton);
					navigationAdded = false;
				}
				return;
			}
			if (sidePanel == null)
			{
				sidePanel = new AfkRecapPanel(recapHistory, itemPresentation);
				navigationButton = NavigationButton.builder()
					.tooltip("AFK Recap")
					.icon(AfkRecapPanel.navigationIcon())
					.priority(6)
					.panel(sidePanel)
					.build();
			}
			sidePanel.refresh();
			if (!navigationAdded)
			{
				clientToolbar.addNavigation(navigationButton);
				navigationAdded = true;
			}
		});
	}

	private void baselineExperience(AfkSessionManager current)
	{
		current.baseline(experienceSnapshot());
		current.baselinePrayer(client.getBoostedSkillLevel(Skill.PRAYER));
	}

	private Map<Skill, Integer> experienceSnapshot()
	{
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			xp.put(skill, client.getSkillExperience(skill));
		}
		return xp;
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import lombok.Getter;
import net.runelite.api.Skill;

/** Immutable completed-session data, independent of logging and rendering. */
@Getter
public final class AfkRecapSession
{
	private final AfkSessionTrigger trigger;
	private final AfkSessionEndReason endReason;
	private final long startGameTick;
	private final Instant startTimestamp;
	private final long endGameTick;
	private final Instant endTimestamp;
	private final long elapsedMillis;
	private final Map<Skill, Long> xpGained;
	private final Set<Skill> relevantIdleSkills;
	private final Map<Integer, Integer> itemGains;
	private final Map<Integer, Integer> notableDrops;
	private final Map<String, Integer> npcKills;
	private final Map<String, Integer> missedRandomEvents;
	private final long prayerUsed;
	private final long damageTaken;

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, Collections.emptyMap());
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, Collections.emptyMap(), 0);
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, npcKills, prayerUsed, 0);
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed, long damageTaken)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, npcKills, prayerUsed, damageTaken, AfkSessionEndReason.UNSPECIFIED);
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed, long damageTaken, AfkSessionEndReason endReason)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, npcKills, prayerUsed, damageTaken, endReason, Collections.emptyMap());
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed, long damageTaken, AfkSessionEndReason endReason,
		Map<Integer, Integer> notableDrops)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, npcKills, prayerUsed, damageTaken, endReason,
			notableDrops, Collections.emptyMap());
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed, long damageTaken, AfkSessionEndReason endReason,
		Map<Integer, Integer> notableDrops, Map<String, Integer> missedRandomEvents)
	{
		Map<String, Integer> misses = new TreeMap<>();
		missedRandomEvents.forEach((name, count) ->
		{
			if (name != null && !name.trim().isEmpty() && count != null && count > 0)
			{
				misses.put(name, count);
			}
		});
		this.missedRandomEvents = Collections.unmodifiableMap(misses);
		Map<Integer, Integer> drops = new TreeMap<>();
		notableDrops.forEach((id, quantity) ->
		{
			if (id >= 0 && quantity > 0)
			{
				drops.put(id, quantity);
			}
		});
		this.notableDrops = Collections.unmodifiableMap(drops);
		this.endReason = endReason;
		this.damageTaken = Math.max(0, damageTaken);
		Map<String, Integer> kills = new TreeMap<>();
		npcKills.forEach((name, count) ->
		{
			if (name != null && !name.trim().isEmpty() && count > 0)
			{
				kills.put(name, count);
			}
		});
		this.npcKills = Collections.unmodifiableMap(kills);
		this.prayerUsed = Math.max(0, prayerUsed);
		this.trigger = trigger;
		this.startGameTick = startGameTick;
		this.startTimestamp = startTimestamp;
		this.endGameTick = endGameTick;
		this.endTimestamp = endTimestamp;
		// Use monotonic elapsed time independently of wall-clock timestamp adjustments.
		this.elapsedMillis = Math.max(0, elapsedMillis);
		EnumMap<Skill, Long> xp = new EnumMap<>(Skill.class);
		xpGained.forEach((skill, gained) ->
		{
			if (gained > 0)
			{
				xp.put(skill, gained);
			}
		});
		this.xpGained = Collections.unmodifiableMap(xp);
		EnumSet<Skill> relevant = EnumSet.noneOf(Skill.class);
		relevant.addAll(relevantIdleSkills);
		this.relevantIdleSkills = Collections.unmodifiableSet(relevant);
		Map<Integer, Integer> items = new TreeMap<>();
		itemGains.forEach((id, quantity) ->
		{
			if (id >= 0 && quantity > 0)
			{
				items.put(id, quantity);
			}
		});
		this.itemGains = Collections.unmodifiableMap(items);
	}

	public boolean hasGains()
	{
		return !missedRandomEvents.isEmpty() || !notableDrops.isEmpty() || !xpGained.isEmpty() || !itemGains.isEmpty() || !npcKills.isEmpty() || prayerUsed > 0 || damageTaken > 0;
	}

	public boolean isIdleRelevant()
	{
		return !relevantIdleSkills.isEmpty() || !missedRandomEvents.isEmpty();
	}

	public long getElapsedGameTicks()
	{
		return endGameTick - startGameTick;
	}
}

package com.afkrecap;

import net.runelite.api.GameState;

/** Completed-session metadata; only classify causes the API actually identifies. */
public enum AfkSessionEndReason
{
	MANUAL_INPUT,
	FOCUS_RETURN,
	LOGOUT,
	DISCONNECT,
	WORLD_HOP,
	LOGOUT_OR_DISCONNECT,
	UNSPECIFIED;

	static AfkSessionEndReason forGameState(GameState state)
	{
		if (state == null)
		{
			return null;
		}
		switch (state)
		{
			case HOPPING: return WORLD_HOP;
			case CONNECTION_LOST: return DISCONNECT;
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
			case LOGGING_IN:
				return LOGOUT_OR_DISCONNECT;
			default: return null;
		}
	}

	boolean isGameExit()
	{
		return this == LOGOUT || this == DISCONNECT || this == WORLD_HOP || this == LOGOUT_OR_DISCONNECT;
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;

// All calls run on the client thread. No rendering or persistent storage belongs here.
@Slf4j
final class AfkSessionManager
{
	private final LongSupplier nanoTime;
	private final Supplier<Instant> timestamp;
	private final Consumer<AfkRecapSession> recapConsumer;
	private final Supplier<Map<Integer, Integer>> inventorySnapshot;
	private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
	private long gameTicks;
	private int inactiveTicks;
	private Session session;
	private Integer prayerPoints;
	private boolean ready = true;
	private boolean loading;

	AfkSessionManager()
	{
		this(System::nanoTime);
	}

	AfkSessionManager(LongSupplier nanoTime)
	{
		this(nanoTime, Instant::now, recap -> {});
	}

	AfkSessionManager(LongSupplier nanoTime, Supplier<Instant> timestamp,
		Consumer<AfkRecapSession> recapConsumer)
	{
		this(nanoTime, timestamp, recapConsumer, () -> null);
	}

	AfkSessionManager(LongSupplier nanoTime, Supplier<Instant> timestamp,
		Consumer<AfkRecapSession> recapConsumer, Supplier<Map<Integer, Integer>> inventorySnapshot)
	{
		this.inventorySnapshot = inventorySnapshot;
		this.nanoTime = nanoTime;
		this.timestamp = timestamp;
		this.recapConsumer = recapConsumer;
	}

	// Clear transient state without publishing (startup, shutdown, synchronization, or after finalization).
	void suspend()
	{
		ready = false;
		loading = false;
		session = null;
		inactiveTicks = 0;
		experience.clear();
		prayerPoints = null;
	}

	void gameStateChanged(GameState state)
	{
		if (state == GameState.LOADING || (state == GameState.LOGGED_IN && loading))
		{
			// A scene load pauses collection, preserving the candidate and its inactivity period.
			ready = false;
			loading = true;
			experience.clear();
			prayerPoints = null;
			if (session != null)
			{
				session.inventory.rebaseline(null);
				session.kills.clearEvidence();
				session.drops.clearEvidence();
				session.randomEvents.clearEvidence();
			}
			return;
		}
		try
		{
			AfkSessionEndReason reason = AfkSessionEndReason.forGameState(state);
			if (session != null && reason != null)
			{
				end(reason, "game state " + state);
			}
		}
		finally
		{
			// Even LOGGED_IN waits for the first stable game tick before accepting activity.
			suspend();
		}
		log.debug("Recap collection suspended for game state {}", state);
	}

	void loggedIn(Map<Skill, Integer> xp, int prayer)
	{
		if (loading)
		{
			if (session != null)
			{
				session.inventory.rebaseline(inventorySnapshot.get());
			}
			loading = false;
		}
		else
		{
			suspend();
		}
		baseline(xp);
		baselinePrayer(prayer);
		ready = true;
	}

	boolean isReady()
	{
		return ready;
	}

	void playerHitsplat(Hitsplat hit)
	{
		if (ready && session != null && PlayerDamage.isDamage(hit))
		{
			session.damageTaken += hit.getAmount();
		}
	}

	void baseline(Map<Skill, Integer> xp)
	{
		experience.clear();
		experience.putAll(xp);
	}

	void gameTick(AfkRecapConfig config)
	{
		if (!ready)
		{
			return;
		}
		if (session != null)
		{
			session.inventory.gameTick();
			configureRandomEvents(config.trackMissedRandomEvents());
			if (session.trackRandomEvents)
			{
				session.randomEvents.gameTick();
			}
		}
		gameTicks++;
		inactiveTicks = Math.min(100, inactiveTicks + 1);
		int threshold = Math.max(1, Math.min(100, config.idleGameTicks()));
		if (session == null && config.startOnIdle() && inactiveTicks >= threshold)
		{
			log.debug("Idle threshold reached: {} inactive game ticks (~{} ms)", inactiveTicks, inactiveTicks * 600L);
			start(AfkSessionTrigger.IDLE, IdleActivity.enabledSkills(config), IdleActivity.enabledActivities(config));
			configureRandomEvents(config.trackMissedRandomEvents());
		}
	}

	void focusChanged(boolean focused, AfkRecapConfig config)
	{
		if (!ready)
		{
			return;
		}
		if (focused)
		{
			if (trigger() == AfkSessionTrigger.FOCUS)
			{
				end(AfkSessionEndReason.FOCUS_RETURN, "focus regained");
				inactiveTicks = 0;
			}
		}
		else if (config.startOnFocusLoss() && session == null)
		{
			start(AfkSessionTrigger.FOCUS, EnumSet.noneOf(Skill.class), EnumSet.noneOf(IdleActivity.class));
			configureRandomEvents(config.trackMissedRandomEvents());
		}
	}

	void manualInput()
	{
		if (!ready)
		{
			return;
		}
		if (trigger() == AfkSessionTrigger.IDLE)
		{
			end(AfkSessionEndReason.MANUAL_INPUT, "manual input");
		}
		// This same input begins the next inactivity period, even when it ends a session.
		inactiveTicks = 0;
	}

	void statChanged(Skill skill, int xp)
	{
		if (!ready)
		{
			return;
		}
		Integer previous = experience.put(skill, xp);
		// A missing baseline is synchronization, not a gain. Decreases rebaseline only.
		if (session == null || previous == null || xp <= previous)
		{
			return;
		}
		long gained = (long) xp - previous;
		session.xpGained.merge(skill, gained, Long::sum);
		if (trigger() == AfkSessionTrigger.IDLE && session.enabledSkills.contains(skill)
			&& session.relevantSkills.add(skill))
		{
			log.debug("IDLE session enabled skill activity detected: {} (+{} XP)", skill, gained);
		}
	}

	void activityDetected(IdleActivity activity)
	{
		if (ready && trigger() == AfkSessionTrigger.IDLE && activity != null
			&& session.enabledActivities.contains(activity))
		{
			activity.addRelevantSkills(session.relevantSkills);
		}
	}

	void baselinePrayer(int points)
	{
		prayerPoints = points;
	}

	void prayerChanged(int points)
	{
		if (!ready)
		{
			return;
		}
		if (session != null && prayerPoints != null && points < prayerPoints)
		{
			session.prayerUsed += (long) prayerPoints - points;
		}
		prayerPoints = points;
	}

	void npcDamage(Object npc, int amount, boolean mine, boolean others)
	{
		if (ready && session != null)
		{
			session.kills.damage(npc, amount, mine, others);
		}
	}

	void npcDeath(Object npc, String name)
	{
		if (ready && session != null)
		{
			session.kills.death(npc, name);
		}
	}

	void npcDespawned(Object npc)
	{
		if (ready && session != null)
		{
			session.kills.despawn(npc);
		}
	}

	void configureRandomEvents(boolean enabled)
	{
		if (session != null)
		{
			session.trackRandomEvents = enabled;
			if (!enabled)
			{
				session.randomEvents.clear();
			}
		}
	}

	void randomEventTargeted(Object npc, int id, String name, boolean targetsLocal, boolean localInteractingBack)
	{
		if (ready && session != null && session.trackRandomEvents)
		{
			session.randomEvents.targeted(npc, id, name, targetsLocal, localInteractingBack);
		}
	}

	void randomEventHandled(Object npc)
	{
		if (ready && session != null && session.trackRandomEvents)
		{
			session.randomEvents.handled(npc);
		}
	}

	void randomEventDespawned(Object npc)
	{
		if (ready && session != null && session.trackRandomEvents)
		{
			session.randomEvents.despawned(npc);
		}
	}

	void groundSpawn(Object pile, int id, int quantity, int ownership, long price, boolean clue, AfkRecapConfig config)
	{
		if (ready && session != null)
		{
			session.drops.spawn(pile, id, quantity, ownership, price, clue, config);
		}
	}

	void groundQuantityChanged(Object pile, int id, int oldQuantity, int newQuantity, int ownership,
		long price, boolean clue, AfkRecapConfig config)
	{
		if (ready && session != null)
		{
			session.drops.quantityChanged(pile, id, oldQuantity, newQuantity, ownership, price, clue, config);
		}
	}

	void groundDespawn(Object pile)
	{
		if (ready && session != null)
		{
			session.drops.despawn(pile);
		}
	}

	void inventoryChanged(Map<Integer, Integer> inventory)
	{
		if (ready && session != null)
		{
			session.inventory.inventoryChanged(inventory);
		}
	}

	void acquisitionMessage(String message, boolean fishStorage, boolean logStorage)
	{
		if (ready && session != null)
		{
			session.inventory.message(message, fishStorage, logStorage);
		}
	}

	void resourceTransfer(ResourceAcquisitionMessages.Family family)
	{
		if (ready && session != null)
		{
			session.inventory.transfer(family);
		}
	}

	void reset(String reason)
	{
		if (session != null)
		{
			end(AfkSessionEndReason.UNSPECIFIED, reason);
		}
		inactiveTicks = 0;
		experience.clear();
		prayerPoints = null;
	}

	AfkSessionTrigger trigger()
	{
		return session == null ? null : session.trigger;
	}

	Set<Skill> relevantSkills()
	{
		return session == null ? EnumSet.noneOf(Skill.class) : EnumSet.copyOf(session.relevantSkills);
	}

	private void start(AfkSessionTrigger trigger, Set<Skill> enabledSkills, Set<IdleActivity> enabledActivities)
	{
		session = new Session(trigger, gameTicks, nanoTime.getAsLong(), timestamp.get(), enabledSkills, enabledActivities, inventorySnapshot.get());
		log.debug("Away session started: trigger={}, gameTick={}, enabledSkills={}", trigger, gameTicks, enabledSkills);
	}

	private void end(AfkSessionEndReason endReason, String reason)
	{
		Session ended = session;
		session = null;
		if (ended.trigger == AfkSessionTrigger.IDLE)
		{
			// Re-arm every idle-session ending centrally, before diagnostics run.
			inactiveTicks = 0;
		}
		Instant endTimestamp = timestamp.get();
		long ticks = gameTicks - ended.startTick;
		long elapsedMillis = (nanoTime.getAsLong() - ended.startNanos) / 1_000_000L;
		String outcome = ended.trigger == AfkSessionTrigger.IDLE
			? (ended.relevantSkills.isEmpty() && ended.randomEvents.misses().isEmpty() ? "discarded" : "relevant") : "ended";
		log.debug("Away session ended: trigger={}, reason={}, outcome={}, skills={}, elapsedGameTicks={}, elapsedMs={}",
			ended.trigger, reason, outcome, ended.relevantSkills, ticks, elapsedMillis);
		Map<Integer, Integer> itemGains = ended.inventory.gains();
		if ((!ended.xpGained.isEmpty() || !itemGains.isEmpty() || !ended.kills.totals().isEmpty()
			|| !ended.drops.totals().isEmpty() || !ended.randomEvents.misses().isEmpty() || ended.prayerUsed > 0 || ended.damageTaken > 0)
			&& (ended.trigger == AfkSessionTrigger.FOCUS || !ended.relevantSkills.isEmpty() || !ended.randomEvents.misses().isEmpty()))
		{
			AfkRecapSession recap = new AfkRecapSession(ended.trigger, ended.startTick,
				ended.startTimestamp, gameTicks, endTimestamp, elapsedMillis,
				ended.xpGained, ended.relevantSkills, itemGains, ended.kills.totals(), ended.prayerUsed, ended.damageTaken, endReason, ended.drops.totals(), ended.randomEvents.misses());
			logRecap(recap);
			// Hand off an immutable snapshot; no session history or permanent storage.
			recapConsumer.accept(recap);
		}
	}

	private void logRecap(AfkRecapSession recap)
	{
		if (!log.isDebugEnabled())
		{
			return;
		}
		StringBuilder message = new StringBuilder("AFK Recap\nTrigger: ")
			.append(recap.getTrigger())
			.append("\nDuration: ").append(recap.getElapsedGameTicks()).append(" ticks / ")
			.append(String.format(Locale.ROOT, "%.1f", recap.getElapsedMillis() / 1000.0))
			.append(" seconds");
		if (!recap.getXpGained().isEmpty())
		{
			message.append("\nXP gained:");
		}
		recap.getXpGained().forEach((skill, gained) ->
			message.append("\n- ").append(skill.getName()).append(": ").append(gained));
		if (!recap.getItemGains().isEmpty())
		{
			message.append("\nItems gained:");
			recap.getItemGains().forEach((id, quantity) ->
				message.append("\n- Item ").append(id).append(": ").append(quantity));
		}
		if (!recap.getMissedRandomEvents().isEmpty())
		{
			message.append("\nMissed random events:");
			recap.getMissedRandomEvents().forEach((name, count) ->
				message.append("\n- ").append(name).append(": ").append(count));
		}

		log.debug("{}", message);
	}

	private static final class Session
	{
		private final AfkSessionTrigger trigger;
		private final long startTick;
		private final long startNanos;
		private final Instant startTimestamp;
		private final Map<Skill, Long> xpGained = new EnumMap<>(Skill.class);
		private final Set<Skill> enabledSkills;
		private final Set<IdleActivity> enabledActivities;
		private final ResourceAcquisitionTracker inventory;
		private boolean trackRandomEvents;
		private final MissedRandomEventTracker randomEvents = new MissedRandomEventTracker();
		private final NpcKillTracker kills = new NpcKillTracker();
		private final NotableDropTracker drops = new NotableDropTracker();
		private long prayerUsed;
		private long damageTaken;
		private final EnumSet<Skill> relevantSkills = EnumSet.noneOf(Skill.class);

		private Session(AfkSessionTrigger trigger, long startTick, long startNanos,
			Instant startTimestamp, Set<Skill> enabledSkills, Set<IdleActivity> enabledActivities, Map<Integer, Integer> inventoryBaseline)
		{
			this.trigger = trigger;
			this.startTick = startTick;
			this.startNanos = startNanos;
			this.startTimestamp = startTimestamp;
			this.inventory = new ResourceAcquisitionTracker(inventoryBaseline);
			this.enabledSkills = EnumSet.noneOf(Skill.class);
			this.enabledSkills.addAll(enabledSkills);
			this.enabledActivities = EnumSet.noneOf(IdleActivity.class);
			this.enabledActivities.addAll(enabledActivities);
		}
	}
}

package com.afkrecap;

public enum AfkSessionTrigger
{
	FOCUS,
	IDLE
}

package com.afkrecap;

import net.runelite.api.gameval.ItemID;

/** RuneLite ClueScrollPlugin's parameter identification covers step variants; see META-INF/NOTICE. */
final class ClueDropItems
{
	private ClueDropItems()
	{
	}

	static boolean isClue(int id, int clueParameter)
	{
		return id == ItemID.TRAIL_CLUE_BEGINNER || id == ItemID.TRAIL_CLUE_MASTER || clueParameter != -1;
	}
