package com.afkrecap;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.Predicate;
import net.runelite.api.Skill;

// XP-driven categories declare skills; signal-driven categories qualify explicitly.
enum IdleActivity
{
	FISHING(AfkRecapConfig::idleFishing, Skill.FISHING),
	MINING(AfkRecapConfig::idleMining, Skill.MINING),
	WOODCUTTING(AfkRecapConfig::idleWoodcutting, Skill.WOODCUTTING),
	SAILING_SALVAGING(AfkRecapConfig::idleSailingSalvaging, false, Skill.SAILING),
	SAILING_SORTING(AfkRecapConfig::idleSailingSorting, false, Skill.SAILING),
	COMBAT(AfkRecapConfig::idleCombat, Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE,
		Skill.RANGED, Skill.MAGIC, Skill.HITPOINTS),
	SLAYER(AfkRecapConfig::idleSlayer, Skill.SLAYER);

	private final Set<Skill> skills;
	private final boolean xpDriven;
	private final Predicate<AfkRecapConfig> enabled;

	IdleActivity(Predicate<AfkRecapConfig> enabled, Skill... skills)
	{
		this(enabled, true, skills);
	}

	IdleActivity(Predicate<AfkRecapConfig> enabled, boolean xpDriven, Skill... skills)
	{
		this.xpDriven = xpDriven;
		this.skills = EnumSet.noneOf(Skill.class);
		this.skills.addAll(Arrays.asList(skills));
		this.enabled = enabled;
	}

	static Set<IdleActivity> enabledActivities(AfkRecapConfig config)
	{
		Set<IdleActivity> activities = EnumSet.noneOf(IdleActivity.class);
		for (IdleActivity activity : values())
		{
			if (activity.enabled.test(config))
			{
				activities.add(activity);
			}
		}
		return activities;
	}

	void addRelevantSkills(Set<Skill> relevantSkills)
	{
		relevantSkills.addAll(skills);
	}

	static Set<Skill> enabledSkills(AfkRecapConfig config)
	{
		Set<Skill> skills = EnumSet.noneOf(Skill.class);
		for (IdleActivity activity : values())
		{
			if (activity.xpDriven && activity.enabled.test(config))
			{
				skills.addAll(activity.skills);
			}
		}
		return skills;
	}
}

package com.afkrecap;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import net.runelite.api.Item;

/** Acquisition deltas across inventory snapshots; null means the baseline is unavailable. */
final class InventoryGainTracker
{
	private Map<Integer, Integer> previous;
	private final Map<Integer, Integer> gains = new HashMap<>();

	InventoryGainTracker(Map<Integer, Integer> baseline)
	{
		previous = baseline == null ? null : new HashMap<>(baseline);
	}

	void baseline(Map<Integer, Integer> snapshot)
	{
		previous = snapshot == null ? null : new HashMap<>(snapshot);
	}

	void update(Map<Integer, Integer> current)
	{
		update(current, id -> true);
	}

	/** Return positive deltas while allowing the caller to defer selected resources. */
	Map<Integer, Integer> update(Map<Integer, Integer> current, IntPredicate countImmediately)
	{
		Map<Integer, Integer> additions = new HashMap<>();
		if (current == null)
		{
			previous = null;
			return additions;
		}
		if (previous != null)
		{
			current.forEach((id, quantity) ->
			{
				int difference = quantity - previous.getOrDefault(id, 0);
				if (difference > 0)
				{
					additions.put(id, difference);
					if (countImmediately.test(id))
					{
						addGain(id, difference);
					}
				}
			});
		}
		previous = new HashMap<>(current);
		return additions;
	}

	void addGain(int id, int quantity)
	{
		if (quantity > 0)
		{
			gains.merge(id, quantity, InventoryGainTracker::addQuantities);
		}
	}

	Map<Integer, Integer> gains()
	{
		return Collections.unmodifiableMap(new HashMap<>(gains));
	}

	static Map<Integer, Integer> totals(Item[] items)
	{
		if (items == null)
		{
			return null;
		}
		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : items)
		{
			if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
			{
				quantities.merge(item.getId(), item.getQuantity(), InventoryGainTracker::addQuantities);
			}
		}
		return quantities;
	}

	static int addQuantities(int first, int second)
	{
		// The recap contract uses Integer quantities; do not overflow into negative gains.
		return (int) Math.min(Integer.MAX_VALUE, (long) first + second);
	}
}

package com.afkrecap;

import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Iterator;
import java.util.WeakHashMap;
import java.util.TreeMap;

// Client-thread, session-scoped evidence. NPC identity avoids index reuse and duplicate signals.
final class MissedRandomEventTracker
{
	private final Map<Object, Event> events = new IdentityHashMap<>();
	// Resolved NPCs are tombstones only; values never retain NPCs. RuneLite NPCs use object equality.
	private final Map<Object, Boolean> resolved = new WeakHashMap<>();
	private final Map<String, Integer> misses = new TreeMap<>();

	void targeted(Object npc, int id, String name, boolean targetsLocal, boolean localInteractingBack)
	{
		if (npc != null && targetsLocal && !localInteractingBack && RandomEventTypes.contains(id)
			&& name != null && !name.trim().isEmpty() && !resolved.containsKey(npc) && !events.containsKey(npc))
		{
			events.put(npc, new Event(name));
		}
	}

	void handled(Object npc)
	{
		Event event = events.get(npc);
		if (event != null)
		{
			event.handled = true;
		}
	}

	void despawned(Object npc)
	{
		Event event = events.get(npc);
		if (event != null)
		{
			event.despawned = true;
		}
	}

	void gameTick()
	{
		Iterator<Map.Entry<Object, Event>> iterator = events.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<Object, Event> entry = iterator.next();
			Event event = entry.getValue();
			if (event.despawned)
			{
				resolved.put(entry.getKey(), Boolean.TRUE);
				iterator.remove();
				if (!event.handled)
				{
					misses.merge(event.name, 1, InventoryGainTracker::addQuantities);
				}
			}
		}
	}

	int activeEventCount()
	{
		return events.size();
	}

	Map<String, Integer> misses()
	{
		return misses;
	}

	void clearEvidence()
	{
		events.clear();
		resolved.clear();
	}

	void clear()
	{
		clearEvidence();
		misses.clear();
	}

	private static final class Event
	{
		private final String name;
		private boolean handled;
		private boolean despawned;

		private Event(String name)
		{
			this.name = name;
		}
	}
}

package com.afkrecap;

import java.util.HashMap;
import java.util.WeakHashMap;
import java.util.Map;
import net.runelite.api.TileItem;

/** Session-local, owned ground piles only. No scene scans or loot-event guesses. */
final class NotableDropTracker
{
	// Scene resets can implicitly despawn piles without ItemDespawned; never retain those objects.
	private final Map<Object, Integer> quantities = new WeakHashMap<>();
	private final Map<Integer, Integer> totals = new HashMap<>();

	static boolean attributed(int ownership)
	{
		return ownership == TileItem.OWNERSHIP_SELF;
	}

	void spawn(Object pile, int id, int quantity, int ownership, long price, boolean clue, AfkRecapConfig config)
	{
		if (pile == null || id < 0 || quantity <= 0 || !attributed(ownership)
			|| !config.trackNotableDrops() || quantities.containsKey(pile))
		{
			return;
		}
		quantities.put(pile, quantity);
		credit(id, quantity, price, clue, config);
	}

	void quantityChanged(Object pile, int id, int oldQuantity, int newQuantity, int ownership,
		long price, boolean clue, AfkRecapConfig config)
	{
		Integer previous = quantities.get(pile);
		// A pre-session pile or out-of-order event is insufficient acquisition evidence.
		if (previous == null || previous != oldQuantity || newQuantity < 0)
		{
			return;
		}
		quantities.put(pile, newQuantity);
		if (attributed(ownership) && config.trackNotableDrops() && newQuantity > oldQuantity)
		{
			credit(id, newQuantity - oldQuantity, price, clue, config);
		}
	}

	void despawn(Object pile)
	{
		quantities.remove(pile);
	}

	private void credit(int id, int quantity, long price, boolean clue, AfkRecapConfig config)
	{
		long threshold = Math.max(0, config.notableDropValue());
		// Compare stack value without multiplying a potentially large price/quantity.
		boolean valuable = price >= 0 && price >= (threshold + quantity - 1L) / quantity;
		if (valuable || (clue && config.alwaysTrackClues()))
		{
			totals.merge(id, quantity, InventoryGainTracker::addQuantities);
		}
	}

	void clearEvidence()
	{
		quantities.clear();
	}

	Map<Integer, Integer> totals()
	{
		return totals;
	}
}

package com.afkrecap;

import java.util.IdentityHashMap;
import java.util.Map;
import java.util.TreeMap;

/** Session-local evidence; NPC object identity avoids index reuse and morph issues. */
final class NpcKillTracker
{
	private final Map<Object, Evidence> evidence = new IdentityHashMap<>();
	private final Map<String, Integer> totals = new TreeMap<>();

	void damage(Object npc, int amount, boolean mine, boolean others)
	{
		if (npc == null || amount <= 0 || (!mine && !others))
		{
			return;
		}
		Evidence hit = evidence.computeIfAbsent(npc, ignored -> new Evidence());
		hit.mine |= mine;
		hit.others |= others;
	}

	void death(Object npc, String name)
	{
		Evidence hit = evidence.get(npc);
		if (hit == null || hit.dead)
		{
			return;
		}
		hit.dead = true;
		if (hit.mine && !hit.others && name != null && !name.trim().isEmpty())
		{
			totals.merge(name, 1, (count, added) -> count == Integer.MAX_VALUE ? count : count + added);
		}
	}

	void despawn(Object npc)
	{
		evidence.remove(npc);
	}

	void clearEvidence()
	{
		evidence.clear();
	}

	Map<String, Integer> totals()
	{
		return totals;
	}

	private static final class Evidence
	{
		private boolean mine;
		private boolean others;
		private boolean dead;
	}
}

package com.afkrecap;

import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

/** Explicit HP-damage types from the installed API; resource drains are not HP damage. */
final class PlayerDamage
{
	private PlayerDamage()
	{
	}

	static boolean isDamage(Hitsplat hit)
	{
		if (hit == null || hit.getAmount() <= 0)
		{
			return false;
		}
		switch (hit.getHitsplatType())
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
			case HitsplatID.BLEED:
			case HitsplatID.BURN:
				return true;
			default:
				return false;
		}
	}
}

package com.afkrecap;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;

/** A deliberately small vocabulary: no XP inference, Check text, or generic success messages. */
final class ResourceAcquisitionMessages
{
	enum Family { FISH, LOG }

	private static final Pattern CATCH = Pattern.compile("^You catch (?:a|an|some)(?: raw)? ([A-Za-z ]+)[.!]$");
	// Adapt RuneLite 1.13.1 WoodcuttingPlugin's acquisition pattern; see META-INF/NOTICE.
	private static final Pattern CHOP = Pattern.compile("^You get (?:some|an)([\\w ]+(?:logs?|mushrooms))\\.$");
	private static final Map<String, Integer> FISH = fish();
	private static final Map<String, Integer> LOGS = logs();

	private ResourceAcquisitionMessages()
	{
	}

	/** Cheap prefilter only; the exact parser still decides whether an item can be credited. */
	static boolean mayAcquire(String message)
	{
		return message != null && (message.startsWith("You catch ") || message.startsWith("You get ")
			|| bonus(message) != null);
	}

	static boolean acceptsChat(Family family, ChatMessageType type)
	{
		return type == ChatMessageType.SPAM || (family == Family.LOG
			&& (type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.MESBOX));
	}

	static Integer resource(String message, Family family)
	{
		if (message == null)
		{
			return null;
		}
		Matcher match = (family == Family.FISH ? CATCH : CHOP).matcher(message);
		return match.matches() ? (family == Family.FISH ? FISH : LOGS)
			.get(match.group(1).trim().toLowerCase(Locale.ROOT)) : null;
	}

	static Family family(int id)
	{
		return FISH.containsValue(id) ? Family.FISH : LOGS.containsValue(id) ? Family.LOG : null;
	}

	static Family container(int id)
	{
		switch (id)
		{
			case ItemID.FISH_BARREL_OPEN:
			case ItemID.FISH_BARREL_CLOSED:
			case ItemID.FISH_SACK_BARREL_OPEN:
			case ItemID.FISH_SACK_BARREL_CLOSED:
				return Family.FISH;
			case ItemID.LOG_BASKET_OPEN:
			case ItemID.LOG_BASKET_CLOSED:
			case ItemID.FORESTRY_BASKET_OPEN:
			case ItemID.FORESTRY_BASKET_CLOSED:
				return Family.LOG;
			default:
				return null;
		}
	}

	static Family bonus(String message)
	{
		switch (message)
		{
			case "Rada's blessing enabled you to catch an extra fish.":
			case "The spirit flakes enabled you to catch an extra fish.":
				return Family.FISH;
			case "Your Kandarin headgear provides you with an additional log.":
			case "The nature offerings enabled you to chop an extra log.":
				return Family.LOG;
			default:
				return null;
		}
	}

	private static Map<String, Integer> fish()
	{
		Map<String, Integer> ids = new HashMap<>();
		ids.put("shrimp", ItemID.RAW_SHRIMP);
		ids.put("shrimps", ItemID.RAW_SHRIMP);
		ids.put("sardine", ItemID.RAW_SARDINE);
		ids.put("herring", ItemID.RAW_HERRING);
		ids.put("anchovies", ItemID.RAW_ANCHOVIES);
		ids.put("mackerel", ItemID.RAW_MACKEREL);
		ids.put("trout", ItemID.RAW_TROUT);
		ids.put("cod", ItemID.RAW_COD);
		ids.put("pike", ItemID.RAW_PIKE);
		ids.put("salmon", ItemID.RAW_SALMON);
		ids.put("tuna", ItemID.RAW_TUNA);
		ids.put("lobster", ItemID.RAW_LOBSTER);
		ids.put("bass", ItemID.RAW_BASS);
		ids.put("swordfish", ItemID.RAW_SWORDFISH);
		ids.put("monkfish", ItemID.RAW_MONKFISH);
		ids.put("karambwan", ItemID.TBWT_RAW_KARAMBWAN);
		ids.put("shark", ItemID.RAW_SHARK);
		ids.put("anglerfish", ItemID.RAW_ANGLERFISH);
		ids.put("dark crab", ItemID.RAW_DARK_CRAB);
		return Collections.unmodifiableMap(ids);
	}

	private static Map<String, Integer> logs()
	{
		Map<String, Integer> ids = new HashMap<>();
		ids.put("logs", ItemID.LOGS);
		ids.put("achey tree logs", ItemID.ACHEY_TREE_LOGS);
		ids.put("oak logs", ItemID.OAK_LOGS);
		ids.put("willow logs", ItemID.WILLOW_LOGS);
		ids.put("teak logs", ItemID.TEAK_LOGS);
		ids.put("maple logs", ItemID.MAPLE_LOGS);
		ids.put("mahogany logs", ItemID.MAHOGANY_LOGS);
		ids.put("arctic pine logs", ItemID.ARCTIC_PINE_LOG);
		ids.put("yew logs", ItemID.YEW_LOGS);
		ids.put("magic logs", ItemID.MAGIC_LOGS);
		ids.put("redwood logs", ItemID.REDWOOD_LOGS);
		new HashMap<>(ids).forEach((name, id) -> ids.put(name.substring(0, name.length() - 1), id));
		return Collections.unmodifiableMap(ids);
	}
}

package com.afkrecap;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import com.afkrecap.ResourceAcquisitionMessages.Family;

/** Session-local reconciliation. Hold one completed tick for delayed inventory/transfer events. */
final class ResourceAcquisitionTracker
{
	private final InventoryGainTracker inventory;
	private final Map<Family, Long> transferUntil = new EnumMap<>(Family.class);
	private Batch previous;
	private Batch current = new Batch();
	private long tick;
	private Integer lastResource;
	private Family lastFamily;
	private final Set<String> bonuses = new HashSet<>();

	ResourceAcquisitionTracker(Map<Integer, Integer> baseline)
	{
		inventory = new InventoryGainTracker(baseline);
	}

	void inventoryChanged(Map<Integer, Integer> snapshot)
	{
		inventory.update(snapshot, id -> ResourceAcquisitionMessages.family(id) == null)
			.forEach((id, count) ->
			{
				Family family = ResourceAcquisitionMessages.family(id);
				if (family != null && !transferring(family))
				{
					current.inventory.merge(id, count, InventoryGainTracker::addQuantities);
					current.available.merge(id, count, InventoryGainTracker::addQuantities);
				}
			});
	}

	void message(String text, boolean fishStorage, boolean logStorage)
	{
		if (text == null)
		{
			return;
		}
		Family bonus = ResourceAcquisitionMessages.bonus(text);
		if (bonus != null)
		{
			// Only an immediately preceding typed acquisition can identify this extra item.
			if (lastResource != null && lastFamily == bonus
				&& (bonus == Family.FISH ? fishStorage : logStorage) && bonuses.add(text))
			{
				current.messages.merge(lastResource, 1, InventoryGainTracker::addQuantities);
			}
			return;
		}
		clearContext();
		for (Family family : Family.values())
		{
			Integer id = ResourceAcquisitionMessages.resource(text, family);
			if (id != null && (family == Family.FISH ? fishStorage : logStorage))
			{
				current.messages.merge(id, 1, InventoryGainTracker::addQuantities);
				lastResource = id;
				lastFamily = family;
				return;
			}
		}
	}

	void transfer(Family family)
	{
		transferUntil.put(family, tick + 2);
		// Completion messages can arrive after the inventory event, including near a tick boundary.
		removeTransfers(current, family);
		if (previous != null)
		{
			removeTransfers(previous, family);
		}
		clearContext();
	}

	void gameTick()
	{
		if (previous != null)
		{
			reconcile();
			commit(previous);
		}
		previous = current;
		current = new Batch();
		tick++;
		clearContext();
	}

	// Commit already observed acquisitions before replacing synchronization baselines.
	void rebaseline(Map<Integer, Integer> snapshot)
	{
		gains();
		inventory.baseline(snapshot);
		transferUntil.clear();
	}

	Map<Integer, Integer> gains()
	{
		reconcile();
		if (previous != null)
		{
			commit(previous);
			previous = null;
		}
		commit(current);
		current = new Batch();
		clearContext();
		return inventory.gains();
	}

	private boolean transferring(Family family)
	{
		Long until = transferUntil.get(family);
		return until != null && tick <= until;
	}

	private void reconcile()
	{
		if (previous != null)
		{
			match(previous, previous);
			match(previous, current);
			match(current, previous);
		}
		match(current, current);
	}

	private void match(Batch messages, Batch additions)
	{
		messages.messages.replaceAll((id, count) ->
		{
			int available = additions.available.getOrDefault(id, 0);
			int matched = Math.min(count, available);
			additions.available.put(id, available - matched);
			// Matched evidence confirms an acquisition now; a subsequent Fill must not erase it.
			additions.inventory.computeIfPresent(id, (item, quantity) -> quantity - matched);
			inventory.addGain(id, matched);
			return count - matched;
		});
	}

	private void commit(Batch batch)
	{
		batch.inventory.forEach(inventory::addGain);
		batch.messages.forEach(inventory::addGain);
	}

	private static void removeTransfers(Batch batch, Family family)
	{
		// Keep confirmed acquisitions; discard uncertain inventory additions during a transfer.
		batch.inventory.keySet().removeIf(id -> ResourceAcquisitionMessages.family(id) == family);
		batch.available.keySet().removeIf(id -> ResourceAcquisitionMessages.family(id) == family);
	}

	private void clearContext()
	{
		lastResource = null;
		lastFamily = null;
		bonuses.clear();
	}

	private static final class Batch
	{
		private final Map<Integer, Integer> inventory = new HashMap<>();
		private final Map<Integer, Integer> available = new HashMap<>();
		private final Map<Integer, Integer> messages = new HashMap<>();
	}
}

package com.afkrecap;

import java.util.Set;
import net.runelite.api.gameval.ItemID;

/** Small inventory/equipment snapshot, never estimated container contents. */
final class ResourceContainerState
{
	private final Set<Integer> items;

	ResourceContainerState(Set<Integer> items)
	{
		this.items = items;
	}

	boolean hasContainer(ResourceAcquisitionMessages.Family family)
	{
		return items.stream().anyMatch(id -> ResourceAcquisitionMessages.container(id) == family);
	}

	boolean hiddenFish()
	{
		return (items.contains(ItemID.FISH_BARREL_OPEN) || items.contains(ItemID.FISH_SACK_BARREL_OPEN))
			&& !items.contains(ItemID.INFERNAL_HARPOON);
	}

	boolean hiddenLogs()
	{
		// Felling ration/XP-only messages are not acquisitions. Typed log messages still are.
		return (items.contains(ItemID.LOG_BASKET_OPEN) || items.contains(ItemID.FORESTRY_BASKET_OPEN))
			&& !items.contains(ItemID.INFERNAL_AXE);
	}
}

package com.afkrecap;

import java.util.regex.Pattern;
import net.runelite.api.gameval.AnimationID;

// Signals adapted from RuneLite 1.13.1 IdleNotifierPlugin and LootTrackerPlugin; see META-INF/NOTICE.
final class SailingActivitySignals
{
	private static final Pattern SORTED = Pattern.compile("You sort through the\\s+\\S+\\s+salvage.*");

	private SailingActivitySignals()
	{
	}

	static IdleActivity animation(int animation)
	{
		switch (animation)
		{
			case AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_IDLE01:
			case AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_2X5_IDLE01:
			case AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_3X8_IDLE01:
			case AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_SALVAGING01:
				return IdleActivity.SAILING_SALVAGING;
			case AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_INTERACT01:
				return IdleActivity.SAILING_SORTING;
			default:
				// Setup/reset/crew/boat animations do not positively identify gathering.
				return null;
		}
	}

	static IdleActivity message(String message)
	{
		return message != null && SORTED.matcher(message).matches() ? IdleActivity.SAILING_SORTING : null;
	}
}

package com.afkrecap;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Skill;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.slf4j.LoggerFactory;
import static org.junit.Assert.*;

public class AfkRecapCollectionTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final AtomicLong now = new AtomicLong();
	private final Instant epoch = Instant.parse("2026-10-04T00:00:00Z");
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkSessionManager manager = new AfkSessionManager(now::get,
		() -> epoch.plusNanos(now.get()), recaps::add);
	private final Logger logger = (Logger) LoggerFactory.getLogger(AfkSessionManager.class);
	private final ListAppender<ILoggingEvent> logs = new ListAppender<>();

	@Before
	public void setUp()
	{
		Map<Skill, Integer> baseline = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			baseline.put(skill, 1000);
		}
		manager.baseline(baseline);
		logs.start();
		logger.addAppender(logs);
	}

	@After
	public void tearDown()
	{
		logger.detachAppender(logs);
		logs.stop();
	}

	private void startFocus()
	{
		manager.focusChanged(false, config);
	}

	private void endFocus()
	{
		manager.focusChanged(true, config);
	}

	private void ticks(int count)
	{
		for (int i = 0; i < count; i++)
		{
			manager.gameTick(config);
		}
	}

	private void startIdle()
	{
		manager.manualInput();
		ticks(10);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
	}

	private AfkRecapSession onlyRecap()
	{
		assertEquals(1, recaps.size());
		return recaps.get(0);
	}

	private long recapLogCount()
	{
		return logs.list.stream().map(ILoggingEvent::getFormattedMessage)
			.filter(message -> message.startsWith("AFK Recap\n")).count();
	}

	@Test
	public void oneXpGainProducesFocusRecap()
	{
		startFocus();
		manager.statChanged(Skill.ATTACK, 1025);
		endFocus();
		assertEquals(AfkSessionTrigger.FOCUS, onlyRecap().getTrigger());
		assertEquals(Collections.singletonMap(Skill.ATTACK, 25L), onlyRecap().getXpGained());
		assertEquals(1, recapLogCount());
	}

	@Test
	public void multipleXpGainsInOneSkillAccumulate()
	{
		startFocus();
		manager.statChanged(Skill.WOODCUTTING, 1025);
		manager.statChanged(Skill.WOODCUTTING, 1075);
		manager.statChanged(Skill.WOODCUTTING, 1100);
		endFocus();
		assertEquals(Collections.singletonMap(Skill.WOODCUTTING, 100L), onlyRecap().getXpGained());
	}

	@Test
	public void multipleSkillsAccumulateIndependently()
	{
		startFocus();
		manager.statChanged(Skill.WOODCUTTING, 1525);
		manager.statChanged(Skill.HITPOINTS, 1012);
		manager.statChanged(Skill.SAILING, 1030);
		manager.statChanged(Skill.HITPOINTS, 1020);
		endFocus();
		Map<Skill, Long> xp = onlyRecap().getXpGained();
		assertEquals(3, xp.size());
		assertEquals(Long.valueOf(525), xp.get(Skill.WOODCUTTING));
		assertEquals(Long.valueOf(20), xp.get(Skill.HITPOINTS));
		assertEquals(Long.valueOf(30), xp.get(Skill.SAILING));
	}

	@Test
	public void duplicateStatValuesDoNotDoubleCount()
	{
		startFocus();
		manager.statChanged(Skill.MINING, 1000);
		manager.statChanged(Skill.MINING, 1025);
		manager.statChanged(Skill.MINING, 1025);
		endFocus();
		assertEquals(Collections.singletonMap(Skill.MINING, 25L), onlyRecap().getXpGained());
	}

	@Test
	public void firstStatSynchronizationIsOnlyABaseline()
	{
		manager.baseline(Collections.emptyMap());
		startFocus();
		manager.statChanged(Skill.WOODCUTTING, 50000);
		manager.statChanged(Skill.HITPOINTS, 20000);
		manager.statChanged(Skill.WOODCUTTING, 50025);
		endFocus();
		assertEquals(Collections.singletonMap(Skill.WOODCUTTING, 25L), onlyRecap().getXpGained());
	}

	@Test
	public void explicitBaselineSynchronizationDoesNotAddXp()
	{
		startFocus();
		manager.baseline(Collections.singletonMap(Skill.MINING, 50000));
		manager.statChanged(Skill.MINING, 50000);
		manager.statChanged(Skill.MINING, 50010);
		endFocus();
		assertEquals(Collections.singletonMap(Skill.MINING, 10L), onlyRecap().getXpGained());
	}

	@Test
	public void xpOutsideASessionIsExcluded()
	{
		manager.statChanged(Skill.ATTACK, 1100);
		startFocus();
		manager.statChanged(Skill.ATTACK, 1110);
		endFocus();
		assertEquals(Collections.singletonMap(Skill.ATTACK, 10L), onlyRecap().getXpGained());
	}

	@Test
	public void decreasingXpNeverSubtractsFromRecordedGains()
	{
		startFocus();
		manager.statChanged(Skill.MINING, 1025);
		manager.statChanged(Skill.MINING, 900);
		manager.statChanged(Skill.MINING, 905);
		endFocus();
		assertEquals(Collections.singletonMap(Skill.MINING, 30L), onlyRecap().getXpGained());
	}

	@Test
	public void discardedIdleCandidateDoesNotEmitRecapEvenWithOtherXp()
	{
		startIdle();
		manager.statChanged(Skill.PRAYER, 1012);
		manager.manualInput();
		assertNull(manager.trigger());
		assertTrue(recaps.isEmpty());
		assertEquals(0, recapLogCount());
		assertTrue(logs.list.stream().map(ILoggingEvent::getFormattedMessage)
			.anyMatch(message -> message.contains("outcome=discarded")));
	}

	@Test
	public void disabledIdleSkillDoesNotMakeCandidateRelevant()
	{
		AfkRecapConfig noWoodcutting = new AfkRecapConfig()
		{
			@Override public boolean idleWoodcutting() { return false; }
		};
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(noWoodcutting);
		}
		manager.statChanged(Skill.WOODCUTTING, 1525);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
		assertEquals(0, recapLogCount());
	}

	@Test
	public void relevantIdleIncludesAllXpAndLogsDuration()
	{
		startIdle();
		manager.statChanged(Skill.HITPOINTS, 1012);
		manager.statChanged(Skill.WOODCUTTING, 1525);
		ticks(38);
		now.set(23_300_000_000L);
		manager.manualInput();
		AfkRecapSession recap = onlyRecap();
		assertEquals(AfkSessionTrigger.IDLE, recap.getTrigger());
		assertEquals(10, recap.getStartGameTick());
		assertEquals(48, recap.getEndGameTick());
		assertEquals(38, recap.getElapsedGameTicks());
		assertEquals(epoch, recap.getStartTimestamp());
		assertEquals(epoch.plusMillis(23300), recap.getEndTimestamp());
		assertEquals(23300, recap.getElapsedMillis());
		assertEquals(java.util.EnumSet.of(Skill.WOODCUTTING, Skill.HITPOINTS), recap.getRelevantIdleSkills());
		assertEquals(Long.valueOf(525), recap.getXpGained().get(Skill.WOODCUTTING));
		assertEquals(Long.valueOf(12), recap.getXpGained().get(Skill.HITPOINTS));
		String message = logs.list.stream().map(ILoggingEvent::getFormattedMessage)
			.filter(value -> value.startsWith("AFK Recap\n")).findFirst().get();
		assertTrue(message.contains("Trigger: IDLE\nDuration: 38 ticks / 23.3 seconds"));
		assertTrue(message.contains("- Woodcutting: 525"));
		assertTrue(message.contains("- Hitpoints: 12"));
		assertFalse(message.contains("- Mining:"));
	}

	@Test
	public void focusWithNoXpDoesNotEmitEmptyRecap()
	{
		startFocus();
		manager.statChanged(Skill.MINING, 1000);
		manager.statChanged(Skill.FISHING, 900);
		endFocus();
		assertNull(manager.trigger());
		assertTrue(recaps.isEmpty());
		assertEquals(0, recapLogCount());
	}

	@Test
	public void repeatIdleRecapsHaveIndependentTotalsAndSnapshots()
	{
		startIdle();
		manager.statChanged(Skill.WOODCUTTING, 1025);
		manager.manualInput();
		ticks(9);
		assertNull(manager.trigger());
		ticks(1);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		manager.statChanged(Skill.WOODCUTTING, 1075);
		manager.manualInput();
		assertEquals(2, recaps.size());
		assertEquals(Long.valueOf(25), recaps.get(0).getXpGained().get(Skill.WOODCUTTING));
		assertEquals(Long.valueOf(50), recaps.get(1).getXpGained().get(Skill.WOODCUTTING));
		manager.reset("test shutdown");
		assertEquals(Long.valueOf(25), recaps.get(0).getXpGained().get(Skill.WOODCUTTING));
	}

	@Test(expected = UnsupportedOperationException.class)
	public void completedXpMapIsImmutable()
	{
		startFocus();
		manager.statChanged(Skill.ATTACK, 1025);
		endFocus();
		onlyRecap().getXpGained().put(Skill.MINING, 1L);
	}

	@Test(expected = UnsupportedOperationException.class)
	public void completedRelevantSkillsAreImmutable()
	{
		startIdle();
		manager.statChanged(Skill.FISHING, 1025);
		manager.manualInput();
		onlyRecap().getRelevantIdleSkills().add(Skill.MINING);
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapCombatTest
{
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L, Instant::now,
		recaps::add, () -> Collections.emptyMap());

	private void start()
	{
		manager.baseline(Collections.singletonMap(Skill.ATTACK, 100));
		manager.baselinePrayer(100);
		manager.focusChanged(false, config);
	}

	private AfkRecapSession end()
	{
		manager.statChanged(Skill.ATTACK, 110);
		manager.focusChanged(true, config);
		assertEquals(1, recaps.size());
		return recaps.get(0);
	}

	private void kill(String name)
	{
		Object npc = new Object();
		manager.npcDamage(npc, 10, true, false);
		manager.npcDeath(npc, name);
	}

	@Test public void cumulativePrayerDecreases()
	{
		start();
		manager.prayerChanged(90);
		manager.prayerChanged(80);
		assertEquals(20, end().getPrayerUsed());
	}

	@Test public void restorationNeverSubtracts()
	{
		start();
		manager.prayerChanged(90);
		manager.prayerChanged(115);
		assertEquals(10, end().getPrayerUsed());
	}

	@Test public void multipleDrainRestoreCycles()
	{
		start();
		manager.prayerChanged(90);
		manager.prayerChanged(115);
		manager.prayerChanged(100);
		manager.prayerChanged(120);
		manager.prayerChanged(120);
		manager.prayerChanged(110);
		assertEquals(35, end().getPrayerUsed());
	}

	@Test public void zeroPrayerAndEmptyKillsOmittedFromPresentation()
	{
		start();
		manager.prayerChanged(115);
		AfkRecapController controller = new AfkRecapController(() -> 0L);
		controller.show(end(), true, 10);
		assertNull(controller.visiblePresentation(true).getPrayerUsed());
		assertTrue(controller.visiblePresentation(true).getNpcKills().isEmpty());
	}

	@Test public void oneAttributedKill()
	{
		start();
		kill("Abyssal demon");
		assertEquals(Collections.singletonMap("Abyssal demon", 1), end().getNpcKills());
	}

	@Test public void multipleKillsOfSameNpc()
	{
		start();
		kill("Abyssal demon");
		kill("Abyssal demon");
		assertEquals(Collections.singletonMap("Abyssal demon", 2), end().getNpcKills());
	}

	@Test public void multipleNpcTypes()
	{
		start();
		kill("Abyssal demon");
		kill("Cow");
		AfkRecapSession recap = end();
		assertEquals(2, recap.getNpcKills().size());
		assertEquals(Integer.valueOf(1), recap.getNpcKills().get("Cow"));
	}

	@Test public void unrelatedAndOtherPlayerDeathsExcluded()
	{
		start();
		manager.npcDeath(new Object(), "Cow");
		Object npc = new Object();
		manager.npcDamage(npc, 10, false, true);
		manager.npcDeath(npc, "Cow");
		assertTrue(end().getNpcKills().isEmpty());
	}

	@Test public void contestedKillExcludedEvenWhenOwnHitIsLast()
	{
		start();
		Object npc = new Object();
		manager.npcDamage(npc, 10, false, true);
		manager.npcDamage(npc, 10, true, false);
		manager.npcDeath(npc, "Cow");
		assertTrue(end().getNpcKills().isEmpty());
	}

	@Test public void zeroDamageIsInsufficientAndDuplicateDeathCountedOnce()
	{
		start();
		Object blocked = new Object();
		manager.npcDamage(blocked, 0, true, false);
		manager.npcDeath(blocked, "Cow");
		Object npc = new Object();
		manager.npcDamage(npc, 1, true, false);
		manager.npcDeath(npc, "Cow");
		manager.npcDeath(npc, "Cow");
		assertEquals(Collections.singletonMap("Cow", 1), end().getNpcKills());
	}

	@Test public void despawnClearsEvidence()
	{
		start();
		Object npc = new Object();
		manager.npcDamage(npc, 1, true, false);
		manager.npcDespawned(npc);
		manager.npcDeath(npc, "Cow");
		assertTrue(end().getNpcKills().isEmpty());
	}

	@Test public void preSessionDamageAndPrayerExcluded()
	{
		Object npc = new Object();
		manager.npcDamage(npc, 1, true, false);
		manager.prayerChanged(50);
		start();
		manager.npcDeath(npc, "Cow");
		AfkRecapSession recap = end();
		assertTrue(recap.getNpcKills().isEmpty());
		assertEquals(0, recap.getPrayerUsed());
	}

	@Test public void metricsAloneNeverMakeIdleRelevant()
	{
		manager.baselinePrayer(100);
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(config);
		}
		kill("Cow");
		manager.prayerChanged(90);
		assertTrue(manager.relevantSkills().isEmpty());
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test public void relevantCombatRecapContainsAllMetrics()
	{
		manager.baseline(Collections.singletonMap(Skill.ATTACK, 100));
		manager.baselinePrayer(100);
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(config);
		}
		manager.statChanged(Skill.ATTACK, 125);
		kill("Abyssal demon");
		manager.prayerChanged(57);
		manager.inventoryChanged(Collections.singletonMap(ItemID.COINS, 100));
		manager.manualInput();
		AfkRecapSession recap = recaps.get(0);
		assertEquals(Long.valueOf(25), recap.getXpGained().get(Skill.ATTACK));
		assertEquals(Integer.valueOf(1), recap.getNpcKills().get("Abyssal demon"));
		assertEquals(43, recap.getPrayerUsed());
		assertEquals(Integer.valueOf(100), recap.getItemGains().get(ItemID.COINS));
		AfkRecapController controller = new AfkRecapController(() -> 0L);
		controller.show(recap, true, 10);
		assertEquals("43", controller.visiblePresentation(true).getPrayerUsed());
		assertEquals(recap.getNpcKills(), controller.visiblePresentation(true).getNpcKills());
		AfkRecapHistory history = new AfkRecapHistory();
		history.add(recap);
		assertSame(recap, history.snapshot().get(0));
	}

	@Test public void focusPrayerOnlyRecapAndNextSessionIndependent()
	{
		start();
		manager.prayerChanged(90);
		manager.focusChanged(true, config);
		assertEquals(10, recaps.get(0).getPrayerUsed());
		manager.prayerChanged(80);
		manager.focusChanged(false, config);
		manager.prayerChanged(75);
		manager.focusChanged(true, config);
		assertEquals(5, recaps.get(1).getPrayerUsed());
	}

	@Test public void missingPrayerBaselineAndExplicitSynchronizationAreNotUsage()
	{
		manager.focusChanged(false, config);
		manager.prayerChanged(100);
		manager.baselinePrayer(50);
		manager.prayerChanged(45);
		assertEquals(5, end().getPrayerUsed());
	}

	@Test public void killTotalSaturatesRatherThanBecomingNegative()
	{
		NpcKillTracker tracker = new NpcKillTracker();
		tracker.totals().put("Cow", Integer.MAX_VALUE);
		Object npc = new Object();
		tracker.damage(npc, 1, true, false);
		tracker.death(npc, "Cow");
		assertEquals(Integer.valueOf(Integer.MAX_VALUE), tracker.totals().get("Cow"));
	}

	@Test public void panelShowsMetricsAndOmitsEmptySections() throws Exception
	{
		start();
		kill("Cow");
		manager.prayerChanged(90);
		AfkRecapSession recap = end();
		AfkRecapHistory history = new AfkRecapHistory();
		history.add(recap);
		javax.swing.SwingUtilities.invokeAndWait(() ->
		{
			AfkRecapPanel panel = new AfkRecapPanel(history, new AfkRecapItemPresentation(id -> null));
			List<String> labels = new ArrayList<>();
			labels(panel, labels);
			assertTrue(labels.contains("Kills"));
			assertTrue(labels.contains("Cow"));
			assertTrue(labels.contains("Prayer used: 10"));
			history.clear();
			history.add(new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
				1, Instant.EPOCH, 600, Collections.singletonMap(Skill.ATTACK, 1L),
				Collections.emptySet()));
			panel.refresh();
			labels.clear();
			labels(panel, labels);
			assertFalse(labels.contains("Kills"));
			assertFalse(labels.stream().anyMatch(label -> label.startsWith("Prayer used:")));
		});
	}

	private static void labels(java.awt.Container container, List<String> labels)
	{
		for (java.awt.Component component : container.getComponents())
		{
			if (component instanceof javax.swing.JLabel)
			{
				labels.add(((javax.swing.JLabel) component).getText());
			}
			if (component instanceof java.awt.Container)
			{
				labels((java.awt.Container) component, labels);
			}
		}
	}

	@Test(expected = UnsupportedOperationException.class)
	public void killSnapshotImmutable()
	{
		start();
		kill("Cow");
		end().getNpcKills().put("Cow", 99);
	}
}

package com.afkrecap;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Skill;
import org.junit.Test;
import org.slf4j.LoggerFactory;
import static org.junit.Assert.*;

public class AfkRecapControllerTest
{
	private final AtomicLong now = new AtomicLong();
	private final AfkRecapController controller = new AfkRecapController(now::get);

	private AfkRecapSession recap(AfkSessionTrigger trigger, long durationMillis,
		Map<Skill, Long> xp, Set<Skill> relevant)
	{
		return new AfkRecapSession(trigger, 0, Instant.EPOCH, 33,
			Instant.EPOCH.plusMillis(durationMillis), durationMillis, xp, relevant);
	}

	private AfkRecapSession focusRecap(long xp)
	{
		return recap(AfkSessionTrigger.FOCUS, 19900,
			Collections.singletonMap(Skill.WOODCUTTING, xp), Collections.emptySet());
	}

	private void seconds(long seconds)
	{
		now.set(TimeUnit.SECONDS.toNanos(seconds));
	}

	@Test
	public void noCompletedRecapMeansNoPresentation()
	{
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void defaultDurationExpiresExactlyAtTenSeconds()
	{
		controller.show(focusRecap(337), true, new AfkRecapConfig() {}.overlayDurationSeconds());
		now.set(TimeUnit.SECONDS.toNanos(10) - 1);
		assertNotNull(controller.visiblePresentation(true));
		seconds(10);
		assertNull(controller.visiblePresentation(true));
		seconds(100);
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void newestRecapReplacesPreviousAndRestartsTimer()
	{
		controller.show(focusRecap(337), true, 10);
		seconds(9);
		controller.show(focusRecap(525), true, 10);
		seconds(10);
		assertEquals("+525 XP", controller.visiblePresentation(true).getXpRows().get(0).getGained());
		seconds(18);
		assertNotNull(controller.visiblePresentation(true));
		seconds(19);
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void configuredDurationAndBoundsAreRespected()
	{
		for (int configured : new int[]{1, 3, 20, 60, 100})
		{
			now.set(0);
			controller.show(focusRecap(337), true, configured);
			int expected = Math.max(3, Math.min(60, configured));
			now.set(TimeUnit.SECONDS.toNanos(expected) - 1);
			assertNotNull(controller.visiblePresentation(true));
			seconds(expected);
			assertNull(controller.visiblePresentation(true));
		}
	}

	@Test
	public void disablingClearsAndReenablingDoesNotResurrectRecap()
	{
		controller.show(focusRecap(337), true, 10);
		assertNull(controller.visiblePresentation(false));
		assertNull(controller.visiblePresentation(true));
		controller.show(focusRecap(525), true, 10);
		assertNotNull(controller.visiblePresentation(true));
	}

	@Test
	public void recapReceivedWhileDisabledIsNotQueued()
	{
		controller.show(focusRecap(337), false, 10);
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void emptyFocusRecapIsNotShown()
	{
		controller.show(focusRecap(0), true, 10);
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void discardedIdleCandidateIsNotShown()
	{
		controller.show(recap(AfkSessionTrigger.IDLE, 19900,
			Collections.singletonMap(Skill.HITPOINTS, 12L), Collections.emptySet()), true, 10);
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void discardedCandidateDoesNotReplaceOrExtendCurrentRecap()
	{
		controller.show(focusRecap(337), true, 10);
		seconds(9);
		controller.show(recap(AfkSessionTrigger.IDLE, 19900,
			Collections.singletonMap(Skill.HITPOINTS, 12L), Collections.emptySet()), true, 10);
		assertEquals("Focus", controller.visiblePresentation(true).getTrigger());
		seconds(10);
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void labelsAndXpRowsAreHumanReadableAndExcludeZeroXp()
	{
		Map<Skill, Long> xp = new EnumMap<>(Skill.class);
		xp.put(Skill.WOODCUTTING, 337L);
		xp.put(Skill.HITPOINTS, 12L);
		xp.put(Skill.MINING, 0L);
		controller.show(recap(AfkSessionTrigger.IDLE, 19900, xp,
			Collections.singleton(Skill.WOODCUTTING)), true, 10);
		AfkRecapController.Presentation view = controller.visiblePresentation(true);
		assertEquals("Idle", view.getTrigger());
		assertEquals("19.9s", view.getDuration());
		assertEquals(2, view.getXpRows().size());
		assertTrue(view.getXpRows().stream().anyMatch(row ->
			row.getSkill().equals("Woodcutting") && row.getGained().equals("+337 XP")));
		assertTrue(view.getXpRows().stream().anyMatch(row ->
			row.getSkill().equals("Hitpoints") && row.getGained().equals("+12 XP")));
		controller.show(focusRecap(337), true, 10);
		assertEquals("Focus", controller.visiblePresentation(true).getTrigger());
	}

	@Test
	public void durationFormatsAtMinuteBoundary()
	{
		assertEquals("0.0s", AfkRecapController.formatDuration(0));
		assertEquals("19.9s", AfkRecapController.formatDuration(19900));
		assertEquals("59.9s", AfkRecapController.formatDuration(59900));
		assertEquals("1m 0s", AfkRecapController.formatDuration(60000));
		assertEquals("2m 14s", AfkRecapController.formatDuration(134900));
	}

	@Test
	public void clearRemovesPresentationForLifecycleCleanup()
	{
		controller.show(focusRecap(337), true, 10);
		controller.clear();
		assertNull(controller.visiblePresentation(true));
	}

	@Test
	public void disabledOverlayDoesNotStopXpCollectionOrRecapLogging()
	{
		List<AfkRecapSession> completed = new ArrayList<>();
		AfkSessionManager manager = new AfkSessionManager(now::get, () -> Instant.EPOCH, recap ->
		{
			completed.add(recap);
			controller.show(recap, false, 10);
		});
		Logger logger = (Logger) LoggerFactory.getLogger(AfkSessionManager.class);
		ListAppender<ILoggingEvent> logs = new ListAppender<>();
		logs.start();
		logger.addAppender(logs);
		try
		{
			AfkRecapConfig config = new AfkRecapConfig() {};
			manager.baseline(Collections.singletonMap(Skill.WOODCUTTING, 1000));
			manager.focusChanged(false, config);
			manager.statChanged(Skill.WOODCUTTING, 1337);
			manager.focusChanged(true, config);
			assertEquals(1, completed.size());
			assertEquals(Long.valueOf(337), completed.get(0).getXpGained().get(Skill.WOODCUTTING));
			assertTrue(logs.list.stream().map(ILoggingEvent::getFormattedMessage)
				.anyMatch(message -> message.startsWith("AFK Recap\n")));
			assertNull(controller.visiblePresentation(true));
		}
		finally
		{
			logger.detachAppender(logs);
			logs.stop();
		}
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapDamageLifecycleTest
{
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L, Instant::now, recaps::add);

	private static Hitsplat hit(int type, int amount)
	{
		return new Hitsplat()
		{
			@Override public int getHitsplatType() { return type; }
			@Override public int getAmount() { return amount; }
			@Override public int getDisappearsOnGameCycle() { return 0; }
		};
	}

	private void login(int xp)
	{
		manager.loggedIn(Collections.singletonMap(Skill.ATTACK, xp), 99);
	}

	private void start()
	{
		login(1000);
		manager.focusChanged(false, config);
	}

	private AfkRecapSession end()
	{
		manager.focusChanged(true, config);
		assertEquals(1, recaps.size());
		return recaps.get(0);
	}

	@Test public void oneDamageEvent()
	{
		start();
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 40));
		assertEquals(40, end().getDamageTaken());
	}

	@Test public void severalDamageEventsIncludingPoisonAndVenom()
	{
		start();
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_ME, 40));
		manager.playerHitsplat(hit(HitsplatID.POISON, 6));
		manager.playerHitsplat(hit(HitsplatID.VENOM, 20));
		manager.playerHitsplat(hit(HitsplatID.BURN, 1));
		assertEquals(67, end().getDamageTaken());
	}

	@Test public void healingDoesNotReduceDamage()
	{
		start();
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 40));
		manager.playerHitsplat(hit(HitsplatID.HEAL, 30));
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 20));
		assertEquals(60, end().getDamageTaken());
	}

	@Test public void zeroAndNonDamageHitsplatsIgnored()
	{
		start();
		for (int type : new int[]{HitsplatID.HEAL, HitsplatID.PRAYER_DRAIN,
			HitsplatID.DISEASE, HitsplatID.SANITY_DRAIN, HitsplatID.SANITY_RESTORE,
			HitsplatID.BLOCK_ME, HitsplatID.DAMAGE_ME_POISE})
		{
			manager.playerHitsplat(hit(type, 5));
		}
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 0));
		manager.playerHitsplat(null);
		manager.statChanged(Skill.ATTACK, 1010);
		AfkRecapSession recap = end();
		assertEquals(0, recap.getDamageTaken());
		AfkRecapController controller = new AfkRecapController(() -> 0L);
		controller.show(recap, true, 10);
		assertNull(controller.visiblePresentation(true).getDamageTaken());
	}

	@Test public void damageOutsideSessionIgnored()
	{
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 50));
		start();
		manager.statChanged(Skill.ATTACK, 1010);
		assertEquals(0, end().getDamageTaken());
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 50));
		assertEquals(0, recaps.get(0).getDamageTaken());
	}

	@Test public void damageAloneDoesNotMakeIdleRelevant()
	{
		login(1000);
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 40));
		assertTrue(manager.relevantSkills().isEmpty());
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test public void loginSynchronizationAndStaleFocusProduceNoRecap()
	{
		manager.gameStateChanged(GameState.LOGGED_IN);
		manager.baseline(Collections.singletonMap(Skill.ATTACK, 0));
		manager.focusChanged(false, config);
		manager.statChanged(Skill.ATTACK, 500000);
		manager.statChanged(Skill.HITPOINTS, 200000);
		for (int i = 0; i < 20; i++) { manager.gameTick(config); }
		assertNull(manager.trigger());
		login(500000);
		assertNull(manager.trigger());
		manager.statChanged(Skill.ATTACK, 500000);
		manager.focusChanged(true, config);
		assertTrue(recaps.isEmpty());
	}

	@Test public void firstLegitimateXpGainAfterLoginCounts()
	{
		manager.suspend();
		manager.statChanged(Skill.ATTACK, 500000);
		login(500000);
		manager.focusChanged(false, config);
		manager.statChanged(Skill.ATTACK, 500000);
		manager.statChanged(Skill.ATTACK, 500025);
		assertEquals(Long.valueOf(25), end().getXpGained().get(Skill.ATTACK));
	}

	@Test public void logoutFinalizesActiveSession()
	{
		start();
		manager.statChanged(Skill.ATTACK, 1010);
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 40));
		manager.gameStateChanged(GameState.LOGIN_SCREEN);
		manager.focusChanged(true, config);
		assertNull(manager.trigger());
		assertEquals(1, recaps.size());
		assertEquals(AfkSessionEndReason.LOGOUT_OR_DISCONNECT, recaps.get(0).getEndReason());
		assertEquals(40, recaps.get(0).getDamageTaken());
	}

	@Test public void worldHopFinalizesAndNewWorldHasFreshBaselinesAndTrackers()
	{
		start();
		Object npc = new Object();
		manager.npcDamage(npc, 10, true, false);
		manager.statChanged(Skill.ATTACK, 1010);
		manager.prayerChanged(80);
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 40));
		manager.inventoryChanged(Collections.singletonMap(net.runelite.api.gameval.ItemID.COINS, 10));
		manager.gameStateChanged(GameState.HOPPING);
		assertNull(manager.trigger());
		assertEquals(1, recaps.size());
		assertEquals(AfkSessionEndReason.WORLD_HOP, recaps.get(0).getEndReason());
		recaps.clear();
		manager.statChanged(Skill.ATTACK, 2000);
		manager.gameStateChanged(GameState.LOGGED_IN);
		login(2000);
		assertNull(manager.trigger());
		manager.focusChanged(false, config);
		manager.npcDeath(npc, "Cow");
		manager.statChanged(Skill.ATTACK, 2000);
		manager.statChanged(Skill.ATTACK, 2010);
		AfkRecapSession recap = end();
		assertEquals(Long.valueOf(10), recap.getXpGained().get(Skill.ATTACK));
		assertEquals(0, recap.getPrayerUsed());
		assertEquals(0, recap.getDamageTaken());
		assertTrue(recap.getNpcKills().isEmpty());
		assertTrue(recap.getItemGains().isEmpty());
	}

	@Test public void idleThresholdStartsFreshAfterReconnect()
	{
		login(1000);
		for (int i = 0; i < 9; i++) { manager.gameTick(config); }
		manager.gameStateChanged(GameState.CONNECTION_LOST);
		login(1000);
		for (int i = 0; i < 9; i++) { manager.gameTick(config); }
		assertNull(manager.trigger());
		manager.gameTick(config);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
	}

	@Test public void damageShownInOverlayAndPanel() throws Exception
	{
		start();
		manager.playerHitsplat(hit(HitsplatID.DAMAGE_OTHER, 67));
		AfkRecapSession recap = end();
		AfkRecapController controller = new AfkRecapController(() -> 0L);
		controller.show(recap, true, 10);
		assertEquals("67", controller.visiblePresentation(true).getDamageTaken());
		AfkRecapHistory history = new AfkRecapHistory();
		history.add(recap);
		javax.swing.SwingUtilities.invokeAndWait(() ->
		{
			AfkRecapPanel panel = new AfkRecapPanel(history, new AfkRecapItemPresentation(id -> null));
			assertTrue(hasLabel(panel, "Damage taken: 67"));
			history.clear();
			history.add(new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
				1, Instant.EPOCH, 600, Collections.singletonMap(Skill.ATTACK, 1L),
				Collections.emptySet()));
			panel.refresh();
			assertFalse(hasLabel(panel, "Damage taken: 0"));
			assertFalse(hasLabel(panel, "Damage taken: 67"));
		});
	}

	private static boolean hasLabel(java.awt.Container container, String text)
	{
		for (java.awt.Component child : container.getComponents())
		{
			if (child instanceof javax.swing.JLabel && text.equals(((javax.swing.JLabel) child).getText()))
			{ return true; }
			if (child instanceof java.awt.Container && hasLabel((java.awt.Container) child, text))
			{ return true; }
		}
		return false;
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import javax.swing.SwingUtilities;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapExitTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final AtomicLong nanos = new AtomicLong();
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkRecapHistory history = new AfkRecapHistory();
	private final AfkRecapController overlay = new AfkRecapController(nanos::get);
	private Map<Integer, Integer> inventory = Collections.emptyMap();
	private final AfkSessionManager manager = new AfkSessionManager(nanos::get, () -> Instant.EPOCH,
		recap -> { history.add(recap); overlay.show(recap, true, 10); recaps.add(recap); }, () -> inventory);

	private void login(int xp)
	{
		manager.loggedIn(Map.of(Skill.ATTACK, xp, Skill.HITPOINTS, xp), 99);
	}
	private void ticks(int count)
	{
		for (int i = 0; i < count; i++) { manager.gameTick(config); }
	}
	private void idle() { login(1000); ticks(10); }
	private void focus() { login(1000); manager.focusChanged(false, config); }
	private void items(int count)
	{
		inventory = Map.of(ItemID.COINS, count); manager.inventoryChanged(inventory);
	}
	private void damage(int amount)
	{
		manager.playerHitsplat(new Hitsplat()
		{
			@Override public int getHitsplatType() { return HitsplatID.DAMAGE_OTHER; }
			@Override public int getAmount() { return amount; }
			@Override public int getDisappearsOnGameCycle() { return 0; }
		});
	}

	@Test public void relevantIdleLogoutStoredImmediately()
	{
		idle(); manager.statChanged(Skill.ATTACK, 1010); manager.gameStateChanged(GameState.LOGIN_SCREEN);
		assertEquals(1, history.snapshot().size());
		assertEquals(AfkSessionTrigger.IDLE, recaps.get(0).getTrigger());
		assertEquals(AfkSessionEndReason.LOGOUT_OR_DISCONNECT, recaps.get(0).getEndReason());
		assertNull(manager.trigger()); assertFalse(manager.isReady());
	}

	@Test public void focusLogoutStored()
	{
		focus(); items(10); manager.gameStateChanged(GameState.LOGIN_SCREEN);
		assertEquals(AfkSessionTrigger.FOCUS, history.snapshot().get(0).getTrigger());
	}

	@Test public void irrelevantIdleWithCombatAndItemsIsDiscarded()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean idleCombat() { return false; }
			@Override public boolean idleSlayer() { return false; }
		};
		login(1000); for (int i = 0; i < 10; i++) { manager.gameTick(disabled); }
		manager.statChanged(Skill.ATTACK, 1010); items(10); damage(20);
		manager.gameStateChanged(GameState.LOGIN_SCREEN);
		assertTrue(history.snapshot().isEmpty()); assertNull(manager.trigger());
	}

	@Test public void emptyFocusLogoutDiscarded()
	{
		focus(); manager.gameStateChanged(GameState.LOGIN_SCREEN); assertTrue(history.snapshot().isEmpty());
	}

	@Test public void everyMetricAndPendingResourceSurvivesFinalization()
	{
		idle(); manager.statChanged(Skill.ATTACK, 1040); manager.statChanged(Skill.HITPOINTS, 1013);
		items(10); manager.acquisitionMessage("You get some oak logs.", false, true);
		Object npc = new Object(); manager.npcDamage(npc, 10, true, false); manager.npcDeath(npc, "Cow");
		manager.prayerChanged(90); damage(12); ticks(3); nanos.set(5_000_000_000L);
		manager.gameStateChanged(GameState.LOGIN_SCREEN);
		AfkRecapSession recap = history.snapshot().get(0);
		assertEquals(Map.of(Skill.ATTACK, 40L, Skill.HITPOINTS, 13L), recap.getXpGained());
		assertEquals(Map.of(ItemID.COINS, 10, ItemID.OAK_LOGS, 1), recap.getItemGains());
		assertEquals(Map.of("Cow", 1), recap.getNpcKills()); assertEquals(9, recap.getPrayerUsed());
		assertEquals(12, recap.getDamageTaken()); assertEquals(3, recap.getElapsedGameTicks());
		assertEquals(5000, recap.getElapsedMillis()); assertEquals(AfkSessionTrigger.IDLE, recap.getTrigger());
	}

	@Test public void gameExitNeverOpensOverlay()
	{
		focus(); items(10); manager.gameStateChanged(GameState.LOGIN_SCREEN);
		assertNull(overlay.visiblePresentation(true)); assertEquals(1, history.snapshot().size());
	}

	@Test public void disconnectClearsPreviouslyVisibleOverlay()
	{
		focus(); items(10); manager.focusChanged(true, config); assertNotNull(overlay.visiblePresentation(true));
		manager.focusChanged(false, config); items(12); manager.gameStateChanged(GameState.CONNECTION_LOST);
		assertNull(overlay.visiblePresentation(true)); assertEquals(2, history.snapshot().size());
		assertEquals(AfkSessionEndReason.DISCONNECT, history.snapshot().get(0).getEndReason());
	}

	@Test public void worldHopFinalizesOnlyOnceAndNewWorldStartsClean()
	{
		focus(); manager.statChanged(Skill.ATTACK, 1010); items(10); damage(20);
		Object npc = new Object(); manager.npcDamage(npc, 10, true, false);
		manager.gameStateChanged(GameState.HOPPING); manager.gameStateChanged(GameState.LOGGING_IN);
		assertEquals(1, recaps.size()); assertEquals(AfkSessionEndReason.WORLD_HOP, recaps.get(0).getEndReason());
		manager.gameStateChanged(GameState.LOGGED_IN); manager.statChanged(Skill.ATTACK, 9000); login(9000);
		assertNull(manager.trigger()); manager.focusChanged(false, config);
		manager.npcDeath(npc, "Cow"); manager.statChanged(Skill.ATTACK, 9005); items(12);
		manager.focusChanged(true, config);
		AfkRecapSession next = recaps.get(1);
		assertEquals(Map.of(Skill.ATTACK, 5L), next.getXpGained()); assertEquals(Map.of(ItemID.COINS, 2), next.getItemGains());
		assertTrue(next.getNpcKills().isEmpty()); assertEquals(0, next.getPrayerUsed()); assertEquals(0, next.getDamageTaken());
	}

	@Test public void reconnectHasNoXpItemOrPendingMessageCarryOver()
	{
		focus(); manager.statChanged(Skill.ATTACK, 1010); items(10);
		manager.acquisitionMessage("You get some oak logs.", false, true);
		manager.gameStateChanged(GameState.CONNECTION_LOST);
		manager.statChanged(Skill.ATTACK, 2000); items(100); damage(30);
		manager.gameStateChanged(GameState.LOGGED_IN); login(2000); manager.focusChanged(false, config);
		manager.statChanged(Skill.ATTACK, 2000); items(100); manager.focusChanged(true, config);
		assertEquals(1, recaps.size()); assertEquals(1, history.snapshot().size());
		manager.focusChanged(false, config); manager.statChanged(Skill.ATTACK, 2001); items(101);
		manager.focusChanged(true, config);
		assertEquals(Map.of(Skill.ATTACK, 1L), recaps.get(1).getXpGained());
		assertEquals(Map.of(ItemID.COINS, 1), recaps.get(1).getItemGains());
	}

	@Test public void nextLoginSynchronizationAndStaleFocusCannotCreateRecap()
	{
		focus(); items(10); manager.gameStateChanged(GameState.LOGIN_SCREEN);
		manager.gameStateChanged(GameState.LOGGED_IN); manager.focusChanged(false, config);
		manager.statChanged(Skill.ATTACK, 500000); items(100); login(500000);
		manager.statChanged(Skill.ATTACK, 500000); manager.focusChanged(true, config);
		assertEquals(1, recaps.size()); assertNull(manager.trigger());
		ticks(9); assertNull(manager.trigger()); ticks(1); assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		manager.manualInput(); assertEquals(1, recaps.size());
	}

	@Test public void ambiguousLoginScreenCauseIsNotClaimedAsManualLogout()
	{
		assertEquals(AfkSessionEndReason.LOGOUT_OR_DISCONNECT, AfkSessionEndReason.forGameState(GameState.LOGIN_SCREEN));
		assertEquals(AfkSessionEndReason.DISCONNECT, AfkSessionEndReason.forGameState(GameState.CONNECTION_LOST));
		assertEquals(AfkSessionEndReason.WORLD_HOP, AfkSessionEndReason.forGameState(GameState.HOPPING));
		assertNull(AfkSessionEndReason.forGameState(GameState.LOADING));
	}

	@Test public void manualInputAndFocusReturnReasonsPreserved()
	{
		idle(); manager.statChanged(Skill.ATTACK, 1010); manager.manualInput();
		assertEquals(AfkSessionEndReason.MANUAL_INPUT, recaps.get(0).getEndReason());
		manager.focusChanged(false, config); manager.statChanged(Skill.ATTACK, 1020); manager.focusChanged(true, config);
		assertEquals(AfkSessionEndReason.FOCUS_RETURN, recaps.get(1).getEndReason());
		assertNotNull(overlay.visiblePresentation(true));
	}

	@Test public void historyPanelAvailableWithoutRelogging() throws Exception
	{
		focus(); items(10); manager.gameStateChanged(GameState.LOGIN_SCREEN);
		SwingUtilities.invokeAndWait(() ->
		{
			AfkRecapPanel panel = new AfkRecapPanel(history, new AfkRecapItemPresentation(id -> null));
			panel.refresh(); assertEquals(1, history.snapshot().size());
		});
		assertFalse(manager.isReady());
	}
	@Test public void loadingBeforeExitPreservesQualifyingData()
	{
		// Loading must leave the qualifying session available to terminal finalization.
		focus(); manager.statChanged(Skill.ATTACK, 1010); items(10);
		manager.gameStateChanged(GameState.LOADING);
		manager.gameStateChanged(GameState.LOGIN_SCREEN);
		assertEquals(1, recaps.size());
		assertEquals(Map.of(Skill.ATTACK, 10L), recaps.get(0).getXpGained());
		assertNull(manager.trigger());
		assertFalse(manager.isReady());
	}

}

package com.afkrecap;

import java.time.Instant;
import java.time.ZoneId;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapHistoryTest
{
	private final AfkRecapHistory history = new AfkRecapHistory();

	private AfkRecapSession focus(long timestamp)
	{
		return new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH, 33,
			Instant.ofEpochSecond(timestamp), 19900,
			Collections.singletonMap(Skill.WOODCUTTING, 337L), Collections.emptySet());
	}

	@Test
	public void addsCompletedRecaps()
	{
		AfkRecapSession recap = focus(1);
		assertTrue(history.add(recap));
		assertEquals(Collections.singletonList(recap), history.snapshot());
	}

	@Test
	public void sortsReverseChronologicallyEvenWhenArrivalsAreOutOfOrder()
	{
		AfkRecapSession oldest = focus(1);
		AfkRecapSession newest = focus(3);
		AfkRecapSession middle = focus(2);
		history.add(oldest);
		history.add(newest);
		history.add(middle);
		List<AfkRecapSession> recaps = history.snapshot();
		assertSame(newest, recaps.get(0));
		assertSame(middle, recaps.get(1));
		assertSame(oldest, recaps.get(2));
	}

	@Test
	public void timestampTiesKeepNewestArrivalFirst()
	{
		AfkRecapSession first = focus(1);
		AfkRecapSession second = focus(1);
		history.add(first);
		history.add(second);
		assertSame(second, history.snapshot().get(0));
	}

	@Test
	public void historyLimitDiscardsOldest()
	{
		history.setLimit(2);
		history.add(focus(1));
		AfkRecapSession middle = focus(2);
		AfkRecapSession newest = focus(3);
		history.add(middle);
		history.add(newest);
		assertEquals(2, history.snapshot().size());
		assertSame(newest, history.snapshot().get(0));
		assertSame(middle, history.snapshot().get(1));
		// An older delayed arrival must not evict a more recent completion.
		history.add(focus(0));
		assertSame(middle, history.snapshot().get(1));
	}

	@Test
	public void defaultLimitIsTwenty()
	{
		assertEquals(20, new AfkRecapConfig() {}.recentRecapLimit());
		for (int i = 0; i < 25; i++)
		{
			history.add(focus(i));
		}
		assertEquals(20, history.snapshot().size());
		assertEquals(Instant.ofEpochSecond(5), history.snapshot().get(19).getEndTimestamp());
	}

	@Test
	public void reducingLimitTrimsImmediatelyAndIncreasingDoesNotRestoreDiscardedEntries()
	{
		for (int i = 0; i < 5; i++)
		{
			history.add(focus(i));
		}
		history.setLimit(2);
		assertEquals(2, history.snapshot().size());
		assertEquals(Instant.ofEpochSecond(3), history.snapshot().get(1).getEndTimestamp());
		history.setLimit(10);
		assertEquals(2, history.snapshot().size());
	}

	@Test
	public void limitIsClampedToConfiguredBounds()
	{
		history.setLimit(200);
		for (int i = 0; i < 110; i++)
		{
			history.add(focus(i));
		}
		assertEquals(100, history.snapshot().size());
		history.setLimit(0);
		assertEquals(1, history.snapshot().size());
		assertEquals(Instant.ofEpochSecond(109), history.snapshot().get(0).getEndTimestamp());
	}

	@Test
	public void clearingHistoryAllowsFreshRecaps()
	{
		history.add(focus(1));
		history.clear();
		assertTrue(history.snapshot().isEmpty());
		AfkRecapSession next = focus(2);
		history.add(next);
		assertEquals(Collections.singletonList(next), history.snapshot());
	}

	@Test
	public void disabledSidePanelRetainsHistoryAndOverlayStillReceivesRecaps()
	{
		AtomicLong now = new AtomicLong();
		AfkRecapController overlay = new AfkRecapController(now::get);
		AfkRecapConfig config = new AfkRecapConfig()
		{
			@Override public boolean enableSidePanel() { return sidePanelEnabled; }
		};
		AfkSessionManager manager = new AfkSessionManager(now::get, () -> Instant.EPOCH, recap ->
		{
			overlay.show(recap, config.showOverlay(), config.overlayDurationSeconds());
			history.add(recap);
		});
		manager.baseline(Collections.singletonMap(Skill.WOODCUTTING, 1000));
		manager.focusChanged(false, config);
		manager.statChanged(Skill.WOODCUTTING, 1337);
		manager.focusChanged(true, config);
		sidePanelEnabled = false;
		manager.focusChanged(false, config);
		manager.statChanged(Skill.WOODCUTTING, 1387);
		manager.focusChanged(true, config);
		assertFalse(config.enableSidePanel());
		assertEquals(2, history.snapshot().size());
		assertEquals("+50 XP", overlay.visiblePresentation(true).getXpRows().get(0).getGained());
		sidePanelEnabled = true;
		assertTrue(config.enableSidePanel());
		assertEquals(2, history.snapshot().size());
	}

	@Test
	public void sessionPipelineOnlyAddsRelevantCompletedRecaps()
	{
		AfkRecapConfig config = new AfkRecapConfig() {};
		AfkSessionManager manager = new AfkSessionManager(() -> 0L, () -> Instant.EPOCH, history::add);
		Map<Skill, Integer> baseline = new EnumMap<>(Skill.class);
		baseline.put(Skill.WOODCUTTING, 1000);
		baseline.put(Skill.PRAYER, 1000);
		manager.baseline(baseline);
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(config);
		}
		manager.statChanged(Skill.PRAYER, 1012);
		manager.manualInput();
		assertTrue(history.snapshot().isEmpty());
		manager.focusChanged(false, config);
		manager.focusChanged(true, config);
		assertTrue(history.snapshot().isEmpty());
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(config);
		}
		manager.statChanged(Skill.WOODCUTTING, 1050);
		assertTrue(history.snapshot().isEmpty());
		manager.manualInput();
		assertEquals(1, history.snapshot().size());
		assertEquals(AfkSessionTrigger.IDLE, history.snapshot().get(0).getTrigger());
		manager.focusChanged(false, config);
		manager.statChanged(Skill.PRAYER, 1020);
		manager.focusChanged(true, config);
		assertEquals(2, history.snapshot().size());
		assertEquals(AfkSessionTrigger.FOCUS, history.snapshot().get(0).getTrigger());
	}

	@Test
	public void historyDefensivelyRejectsEmptyAndDiscardedRecaps()
	{
		AfkRecapSession empty = new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
			1, Instant.EPOCH, 600, Collections.emptyMap(), Collections.emptySet());
		AfkRecapSession discarded = new AfkRecapSession(AfkSessionTrigger.IDLE, 0, Instant.EPOCH,
			1, Instant.EPOCH, 600, Collections.singletonMap(Skill.HITPOINTS, 12L), Collections.emptySet());
		assertFalse(history.add(empty));
		assertFalse(history.add(discarded));
		assertTrue(history.snapshot().isEmpty());
	}

	@Test
	public void snapshotIsDetachedFromLaterChanges()
	{
		history.add(focus(1));
		List<AfkRecapSession> snapshot = history.snapshot();
		history.clear();
		assertEquals(1, snapshot.size());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void snapshotsAreImmutable()
	{
		history.snapshot().add(focus(1));
	}

	@Test
	public void panelFormattingUsesLocalCompletionTimeAndGroupedXp()
	{
		AfkRecapSession focus = new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
			33, Instant.parse("2026-10-04T02:09:00Z"), 19900,
			Collections.singletonMap(Skill.WOODCUTTING, 337L), Collections.emptySet());
		assertEquals("22:09 — Focus — 19.9s", AfkRecapPanelPresentation.header(focus,
			ZoneId.of("America/New_York")));
		AfkRecapSession idle = new AfkRecapSession(AfkSessionTrigger.IDLE, 0, Instant.EPOCH,
			110, Instant.parse("2026-10-04T02:05:00Z"), 66000,
			Collections.singletonMap(Skill.WOODCUTTING, 1050L), Collections.singleton(Skill.WOODCUTTING));
		assertEquals("22:05 — Idle — 1m 06s", AfkRecapPanelPresentation.header(idle,
			ZoneId.of("America/New_York")));
		assertEquals("+1,050 XP", AfkRecapPanelPresentation.xp(1050));
	}

	private boolean sidePanelEnabled = true;
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapInventoryTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private Map<Integer, Integer> inventory = new HashMap<>();
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L,
		() -> Instant.EPOCH, recaps::add, () -> inventory);

	@Before
	public void baselineXp()
	{
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			xp.put(skill, 1000);
		}
		manager.baseline(xp);
	}

	private void ticks(int count, AfkRecapConfig settings)
	{
		for (int i = 0; i < count; i++)
		{
			manager.gameTick(settings);
		}
	}

	private void gainItem(int quantity)
	{
		inventory = Collections.singletonMap(ItemID.YEW_LOGS, quantity);
		manager.inventoryChanged(inventory);
	}

	@Test
	public void focusWithOnlyItemsProducesRecapAndIsAcceptedByHistoryAndOverlay()
	{
		manager.focusChanged(false, config);
		gainItem(12);
		manager.focusChanged(true, config);
		assertEquals(1, recaps.size());
		AfkRecapSession recap = recaps.get(0);
		assertTrue(recap.getXpGained().isEmpty());
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 12), recap.getItemGains());
		AfkRecapHistory history = new AfkRecapHistory();
		assertTrue(history.add(recap));
		AfkRecapItemPresentation items = new AfkRecapItemPresentation(id ->
			new AfkRecapItemPresentation.ItemDetails("Yew logs", 270));
		AfkRecapController overlay = new AfkRecapController(() -> 0L);
		overlay.show(recap, true, 10, items.prepare(recap));
		assertNotNull(overlay.visiblePresentation(true));
		assertTrue(overlay.visiblePresentation(true).getXpRows().isEmpty());
		assertEquals(1, overlay.visiblePresentation(true).getItemRows().size());
	}

	@Test
	public void inventoryIsSnapshottedAtEverySessionStart()
	{
		gainItem(10); // Outside a session, no acquisitions are recorded.
		manager.focusChanged(false, config);
		gainItem(12);
		manager.focusChanged(true, config);
		manager.focusChanged(false, config);
		gainItem(15);
		manager.focusChanged(true, config);
		assertEquals(Integer.valueOf(2), recaps.get(0).getItemGains().get(ItemID.YEW_LOGS));
		assertEquals(Integer.valueOf(3), recaps.get(1).getItemGains().get(ItemID.YEW_LOGS));
	}

	@Test
	public void missingInventoryAtStartDoesNotCountFirstSynchronization()
	{
		inventory = null;
		manager.focusChanged(false, config);
		gainItem(100);
		manager.focusChanged(true, config);
		assertTrue(recaps.isEmpty());
		inventory = null;
		manager.focusChanged(false, config);
		gainItem(100);
		gainItem(102);
		manager.focusChanged(true, config);
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 2), recaps.get(0).getItemGains());
	}

	@Test
	public void idleWithItemsButNoQualifyingXpIsDiscarded()
	{
		ticks(10, config);
		gainItem(12);
		manager.statChanged(Skill.PRAYER, 1012);
		manager.manualInput();
		assertNull(manager.trigger());
		assertTrue(recaps.isEmpty());
		ticks(10, config);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
	}

	@Test
	public void relevantIdleIncludesBothXpAndEarlierItemGains()
	{
		ticks(10, config);
		gainItem(12);
		ticks(70, config);
		assertTrue(recaps.isEmpty());
		assertTrue(manager.relevantSkills().isEmpty());
		manager.statChanged(Skill.WOODCUTTING, 1525);
		manager.manualInput();
		assertEquals(Collections.singletonMap(Skill.WOODCUTTING, 525L), recaps.get(0).getXpGained());
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 12), recaps.get(0).getItemGains());
	}

	@Test
	public void repeatedIdleSessionsKeepSeparateAcquisitionTotals()
	{
		ticks(10, config);
		gainItem(2);
		manager.statChanged(Skill.MINING, 1010);
		manager.manualInput();
		ticks(10, config);
		gainItem(5);
		manager.statChanged(Skill.MINING, 1020);
		manager.manualInput();
		assertEquals(Integer.valueOf(2), recaps.get(0).getItemGains().get(ItemID.YEW_LOGS));
		assertEquals(Integer.valueOf(3), recaps.get(1).getItemGains().get(ItemID.YEW_LOGS));
	}

	private void assertDelayedSkillRelevance(Skill skill)
	{
		ticks(10, config);
		gainItem(12);
		ticks(90, config);
		assertTrue(manager.relevantSkills().isEmpty());
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		manager.statChanged(skill, 1050);
		assertTrue(manager.relevantSkills().contains(skill));
		manager.manualInput();
		assertEquals(Collections.singletonMap(skill, 50L), recaps.get(0).getXpGained());
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 12), recaps.get(0).getItemGains());
	}

	@Test
	public void salvagingSignalQualifiesDelayedCandidateAndRetainsEarlierXpAndItems()
	{
		assertTrue(config.idleSailingSalvaging());
		assertFalse(IdleActivity.enabledSkills(config).contains(Skill.SAILING));
		ticks(10, config);
		gainItem(12);
		manager.statChanged(Skill.SAILING, 1050);
		assertTrue(manager.relevantSkills().isEmpty());
		manager.activityDetected(IdleActivity.SAILING_SALVAGING);
		manager.manualInput();
		assertEquals(Long.valueOf(50), recaps.get(0).getXpGained().get(Skill.SAILING));
		assertEquals(Integer.valueOf(12), recaps.get(0).getItemGains().get(ItemID.YEW_LOGS));
	}

	@Test
	public void slayerXpCanQualifyDelayedCandidateAndRetainsEarlierItems()
	{
		assertTrue(config.idleCombat());
		assertTrue(IdleActivity.enabledSkills(config).contains(Skill.SLAYER));
		assertDelayedSkillRelevance(Skill.SLAYER);
	}

	@Test
	public void disabledSailingDoesNotQualifyCandidate()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean idleSailingSalvaging() { return false; }
		};
		assertFalse(IdleActivity.enabledSkills(disabled).contains(Skill.SAILING));
		ticks(10, disabled);
		gainItem(12);
		manager.statChanged(Skill.SAILING, 1050);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void disabledSlayerDoesNotQualifyViaSlayer()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean idleSlayer() { return false; }
		};
		assertFalse(IdleActivity.enabledSkills(disabled).contains(Skill.SLAYER));
		ticks(10, disabled);
		gainItem(12);
		manager.statChanged(Skill.SLAYER, 1050);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void itemGainsAreDefensiveSnapshots()
	{
		Map<Integer, Integer> gains = new HashMap<>();
		gains.put(ItemID.LOGS, 12);
		AfkRecapSession recap = new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
			1, Instant.EPOCH, 600, Collections.emptyMap(), Collections.emptySet(), gains);
		gains.clear();
		assertEquals(Collections.singletonMap(ItemID.LOGS, 12), recap.getItemGains());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void itemGainsAreImmutable()
	{
		manager.focusChanged(false, config);
		gainItem(12);
		manager.focusChanged(true, config);
		recaps.get(0).getItemGains().put(ItemID.COINS, 1);
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapItemPresentationTest
{
	private AfkRecapSession recap(Map<Integer, Integer> items)
	{
		return new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH, 1, Instant.EPOCH,
			600, Collections.emptyMap(), Collections.emptySet(), items);
	}

	@Test
	public void itemNamesQuantitiesAndPerItemValuesAreFormatted()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
			new AfkRecapItemPresentation.ItemDetails("Yew logs", 270));
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.singletonMap(ItemID.YEW_LOGS, 12)));
		AfkRecapItemPresentation.ItemRow row = display.getRows().get(0);
		assertEquals("Yew logs", row.getName());
		assertEquals("12", row.getQuantity());
		assertEquals("3,240 gp", row.getValue());
		assertEquals("12  3,240 gp", row.getQuantityAndValue());
		assertEquals("3,240 gp", display.getTotalValue());
	}

	@Test
	public void totalGpAddsOnlyPricedItems()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
			id == ItemID.YEW_LOGS ? new AfkRecapItemPresentation.ItemDetails("Yew logs", 270)
			: id == ItemID.BIRD_NEST_EMPTY ? new AfkRecapItemPresentation.ItemDetails("Bird nest", 4812)
			: new AfkRecapItemPresentation.ItemDetails("Unpriced item", 0));
		Map<Integer, Integer> items = new HashMap<>();
		items.put(ItemID.YEW_LOGS, 12);
		items.put(ItemID.BIRD_NEST_EMPTY, 1);
		items.put(ItemID.TINDERBOX, 1);
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(items));
		assertEquals(3, display.getRows().size());
		assertEquals("8,052 gp", display.getTotalValue());
		assertTrue(display.getRows().stream().anyMatch(row ->
			row.getName().equals("Unpriced item") && row.getValue() == null));
	}

	@Test
	public void knownUnpricedItemStillShowsNameAndQuantityWithoutTotal()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
			new AfkRecapItemPresentation.ItemDetails("Untradeable resource", 0));
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.singletonMap(ItemID.LOGS, 1050)));
		assertEquals("Untradeable resource", display.getRows().get(0).getName());
		assertEquals("1,050", display.getRows().get(0).getQuantityAndValue());
		assertNull(display.getRows().get(0).getValue());
		assertNull(display.getTotalValue());
	}

	@Test
	public void unknownItemUsesIdFallbackAndNoInventedValue()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id -> null);
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.singletonMap(ItemID.LOGS, 2)));
		assertEquals("Item " + ItemID.LOGS, display.getRows().get(0).getName());
		assertEquals("2", display.getRows().get(0).getQuantity());
		assertNull(display.getTotalValue());
	}

	@Test
	public void lookupFailureDoesNotFailRecap()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
		{
			throw new IllegalArgumentException("Missing item definition");
		});
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.singletonMap(ItemID.LOGS, 2)));
		assertEquals(1, display.getRows().size());
		assertNull(display.getTotalValue());
	}

	@Test
	public void negativePriceIsNotUseful()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
			new AfkRecapItemPresentation.ItemDetails("Logs", -1));
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.singletonMap(ItemID.LOGS, 2)));
		assertNull(display.getRows().get(0).getValue());
		assertNull(display.getTotalValue());
	}

	@Test
	public void noItemGainsProduceNoItemSection()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
		{
			fail("No lookup should occur for an XP-only recap");
			return null;
		});
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.emptyMap()));
		assertTrue(display.getRows().isEmpty());
		assertNull(display.getTotalValue());
	}

	@Test
	public void cachedPresentationCanBeReadWithoutCallingClientApisAgain()
	{
		AtomicInteger lookups = new AtomicInteger();
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
		{
			lookups.incrementAndGet();
			return new AfkRecapItemPresentation.ItemDetails("Yew logs", 270);
		});
		AfkRecapSession recap = recap(Collections.singletonMap(ItemID.YEW_LOGS, 12));
		AfkRecapItemPresentation.Display display = presenter.prepare(recap);
		assertSame(display, presenter.get(recap));
		assertSame(display, presenter.get(recap));
		assertSame(display, presenter.prepare(recap));
		assertEquals(1, lookups.get());
	}

	@Test
	public void largeValuesDoNotOverflowGpTotals()
	{
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id ->
			new AfkRecapItemPresentation.ItemDetails("Resource", Long.MAX_VALUE));
		AfkRecapItemPresentation.Display display = presenter.prepare(recap(Collections.singletonMap(ItemID.LOGS, 2)));
		assertEquals("18,446,744,073,709,551,614 gp", display.getTotalValue());
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Skill;
import net.runelite.api.TileItem;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapLoadingTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AtomicLong nanos = new AtomicLong();
	private Map<Integer, Integer> inventory = Map.of(ItemID.COINS, 0);
	private final AfkSessionManager manager = new AfkSessionManager(nanos::get,
		() -> Instant.EPOCH, recaps::add, () -> inventory);

	private void login(int xp, int prayer)
	{
		manager.loggedIn(Map.of(Skill.ATTACK, xp, Skill.HITPOINTS, xp), prayer);
	}
	private void ticks(int count)
	{
		for (int i = 0; i < count; i++) { manager.gameTick(config); }
	}
	private void idle() { login(1000, 99); ticks(10); }
	private void focus() { login(1000, 99); manager.focusChanged(false, config); }
	private void items(int count)
	{
		inventory = Map.of(ItemID.COINS, count); manager.inventoryChanged(inventory);
	}
	private void resume()
	{
		manager.gameStateChanged(GameState.LOGGED_IN);
		assertFalse(manager.isReady());
		login(9000, 50);
	}
	private void damage(int amount)
	{
		manager.playerHitsplat(new Hitsplat()
		{
			@Override public int getHitsplatType() { return HitsplatID.DAMAGE_OTHER; }
			@Override public int getAmount() { return amount; }
			@Override public int getDisappearsOnGameCycle() { return 0; }
		});
	}

	@Test public void relevantIdleSurvivesLoadingAndResumesSameSession()
	{
		idle(); manager.statChanged(Skill.ATTACK, 1010);
		manager.gameStateChanged(GameState.LOADING);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertTrue(manager.relevantSkills().contains(Skill.ATTACK));
		assertTrue(recaps.isEmpty()); resume(); ticks(2); nanos.set(7_000_000_000L);
		manager.manualInput();
		AfkRecapSession recap = recaps.get(0);
		assertEquals(AfkSessionTrigger.IDLE, recap.getTrigger());
		assertEquals(10, recap.getStartGameTick()); assertEquals(2, recap.getElapsedGameTicks());
		assertEquals(Instant.EPOCH, recap.getStartTimestamp()); assertEquals(7000, recap.getElapsedMillis());
		assertEquals(Map.of(Skill.ATTACK, 10L), recap.getXpGained());
	}

	@Test public void focusSurvivesLoading()
	{
		focus(); items(10); manager.gameStateChanged(GameState.LOADING);
		manager.focusChanged(true, config); assertTrue(recaps.isEmpty());
		assertEquals(AfkSessionTrigger.FOCUS, manager.trigger()); resume(); manager.focusChanged(true, config);
		assertEquals(AfkSessionTrigger.FOCUS, recaps.get(0).getTrigger());
		assertEquals(Map.of(ItemID.COINS, 10), recaps.get(0).getItemGains());
	}

	@Test public void everyAccumulatedMetricAndPendingResourceSurvivesLoading()
	{
		idle(); manager.statChanged(Skill.ATTACK, 1040); manager.statChanged(Skill.HITPOINTS, 1013);
		items(10); Object cow = new Object(); manager.npcDamage(cow, 10, true, false); manager.npcDeath(cow, "Cow");
		manager.prayerChanged(90); damage(12);
		manager.groundSpawn(new Object(), ItemID.COINS, 1, TileItem.OWNERSHIP_SELF, 1000000, false, config);
		Object genie = new Object(); manager.randomEventTargeted(genie, NpcID.MACRO_GENI, "Genie", true, false);
		manager.randomEventDespawned(genie); ticks(1);
		manager.acquisitionMessage("You get some oak logs.", false, true);
		manager.gameStateChanged(GameState.LOADING); items(100); resume(); manager.manualInput();
		AfkRecapSession recap = recaps.get(0);
		assertEquals(Map.of(Skill.ATTACK, 40L, Skill.HITPOINTS, 13L), recap.getXpGained());
		assertEquals(Map.of(ItemID.COINS, 10, ItemID.OAK_LOGS, 1), recap.getItemGains());
		assertEquals(Map.of(ItemID.COINS, 1), recap.getNotableDrops());
		assertEquals(Map.of("Cow", 1), recap.getNpcKills()); assertEquals(9, recap.getPrayerUsed());
		assertEquals(12, recap.getDamageTaken()); assertEquals(Map.of("Genie", 1), recap.getMissedRandomEvents());
	}

	@Test public void suspendedEventsAndRefreshedBaselinesDoNotCreateGains()
	{
		idle(); manager.statChanged(Skill.ATTACK, 1010); items(10);
		manager.gameStateChanged(GameState.LOADING);
		manager.statChanged(Skill.ATTACK, 5000); manager.prayerChanged(0); damage(100); items(100);
		manager.acquisitionMessage("You get some oak logs.", false, true);
		manager.resourceTransfer(ResourceAcquisitionMessages.Family.LOG);
		Object npc = new Object(); manager.npcDamage(npc, 10, true, false); manager.npcDeath(npc, "Cow");
		manager.groundSpawn(new Object(), ItemID.COINS, 5, TileItem.OWNERSHIP_SELF, 1000000, false, config);
		manager.randomEventTargeted(npc, NpcID.MACRO_GENI, "Genie", true, false); manager.randomEventDespawned(npc);
		ticks(10); manager.manualInput(); assertTrue(recaps.isEmpty());
		manager.gameStateChanged(GameState.LOGGED_IN); manager.statChanged(Skill.ATTACK, 6000); items(200);
		login(9000, 50); manager.statChanged(Skill.ATTACK, 9005); items(202); manager.prayerChanged(49);
		manager.manualInput(); AfkRecapSession recap = recaps.get(0);
		assertEquals(Map.of(Skill.ATTACK, 15L), recap.getXpGained());
		assertEquals(Map.of(ItemID.COINS, 12), recap.getItemGains()); assertEquals(1, recap.getPrayerUsed());
		assertEquals(0, recap.getDamageTaken()); assertTrue(recap.getNpcKills().isEmpty());
		assertTrue(recap.getNotableDrops().isEmpty()); assertTrue(recap.getMissedRandomEvents().isEmpty());
	}

	private void loadingThenExit(GameState state, AfkSessionEndReason reason)
	{
		idle(); manager.statChanged(Skill.ATTACK, 1010); items(10);
		manager.gameStateChanged(GameState.LOADING); manager.gameStateChanged(state);
		manager.gameStateChanged(GameState.LOGIN_SCREEN); manager.gameStateChanged(GameState.LOGGING_IN);
		assertEquals(1, recaps.size()); assertEquals(reason, recaps.get(0).getEndReason());
		assertEquals(Map.of(Skill.ATTACK, 10L), recaps.get(0).getXpGained());
		assertEquals(Map.of(ItemID.COINS, 10), recaps.get(0).getItemGains());
		assertNull(manager.trigger()); assertFalse(manager.isReady());
	}
	@Test public void loadingThenHopFinalizesOnce() { loadingThenExit(GameState.HOPPING, AfkSessionEndReason.WORLD_HOP); }
	@Test public void loadingThenDisconnectFinalizesOnce() { loadingThenExit(GameState.CONNECTION_LOST, AfkSessionEndReason.DISCONNECT); }

	@Test public void loadingAloneNeverPublishesRecap()
	{
		focus(); items(10); manager.gameStateChanged(GameState.LOADING);
		manager.gameStateChanged(GameState.LOADING); ticks(100);
		assertTrue(recaps.isEmpty()); assertEquals(AfkSessionTrigger.FOCUS, manager.trigger());
	}

	@Test public void trueExitClearsPreservedSessionAndBaselines()
	{
		loadingThenExit(GameState.CONNECTION_LOST, AfkSessionEndReason.DISCONNECT);
		items(100); manager.gameStateChanged(GameState.LOADING); resume();
		assertNull(manager.trigger()); manager.focusChanged(false, config);
		manager.statChanged(Skill.ATTACK, 9000); items(100); manager.focusChanged(true, config);
		assertEquals(1, recaps.size());
		manager.focusChanged(false, config); manager.statChanged(Skill.ATTACK, 9001); items(101);
		manager.focusChanged(true, config); assertEquals(2, recaps.size());
		assertEquals(Map.of(Skill.ATTACK, 1L), recaps.get(1).getXpGained());
		assertEquals(Map.of(ItemID.COINS, 1), recaps.get(1).getItemGains());
	}

	@Test public void loadingPreservesInactivityBeforeCandidateStarts()
	{
		login(1000, 99); ticks(9); manager.gameStateChanged(GameState.LOADING); ticks(100);
		resume(); assertNull(manager.trigger()); ticks(1); assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
	}

	@Test public void irrelevantCandidateRetainsDataUntilLaterActivityQualifies()
	{
		idle(); items(10); manager.gameStateChanged(GameState.LOADING); items(100); resume();
		assertTrue(manager.relevantSkills().isEmpty()); manager.statChanged(Skill.ATTACK, 9001); manager.manualInput();
		assertEquals(Map.of(ItemID.COINS, 10), recaps.get(0).getItemGains());
	}

	@Test public void loadingClearsUnconfirmedSceneEvidenceWithoutInventingMissesOrKills()
	{
		focus(); items(10); Object npc = new Object(); manager.npcDamage(npc, 10, true, false);
		manager.randomEventTargeted(npc, NpcID.MACRO_GENI, "Genie", true, false);
		manager.randomEventDespawned(npc); manager.gameStateChanged(GameState.LOADING);
		resume(); manager.npcDeath(npc, "Cow"); ticks(1); manager.focusChanged(true, config);
		assertTrue(recaps.get(0).getNpcKills().isEmpty()); assertTrue(recaps.get(0).getMissedRandomEvents().isEmpty());
	}
}

package com.afkrecap;

import java.awt.Component;
import java.awt.Container;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.TileItem;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapNotableDropsTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L, () -> Instant.EPOCH,
		recaps::add, Collections::emptyMap);
	private final Object pile = new Object();
	private void focus() { manager.focusChanged(false, config); }
	private void drop() { manager.groundSpawn(pile, ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, 1600000, false, config); }
	private AfkRecapSession end() { manager.focusChanged(true, config); return recaps.get(recaps.size() - 1); }

	@Test public void focusWithOnlyNotableDropProducesRecap()
	{
		focus(); drop(); AfkRecapSession recap = end();
		assertTrue(recap.getItemGains().isEmpty()); assertTrue(recap.getXpGained().isEmpty());
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 1), recap.getNotableDrops());
		AfkRecapHistory history = new AfkRecapHistory(); assertTrue(history.add(recap));
	}
	@Test public void laterPickupIntentionallyAppearsInBothMaps()
	{
		focus(); drop(); manager.groundDespawn(pile); manager.inventoryChanged(Map.of(ItemID.ABYSSAL_WHIP, 1));
		AfkRecapSession recap = end();
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 1), recap.getNotableDrops());
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 1), recap.getItemGains());
	}
	@Test public void notableDropAloneNeverQualifiesIdle()
	{
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		drop(); assertTrue(manager.relevantSkills().isEmpty()); manager.manualInput(); assertTrue(recaps.isEmpty());
	}
	@Test public void laterCombatXpRetainsEarlierDrop()
	{
		manager.baseline(Map.of(Skill.ATTACK, 1000));
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		drop(); manager.statChanged(Skill.ATTACK, 1010); manager.manualInput();
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 1), recaps.get(0).getNotableDrops());
	}
	@Test public void outsideSessionDropAndOldPileAdditionIgnored()
	{
		drop(); focus(); manager.groundQuantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		manager.focusChanged(true, config); assertTrue(recaps.isEmpty());
	}
	@Test public void sessionBoundaryClearsPileEvidence()
	{
		focus(); drop(); end(); focus();
		manager.groundQuantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		manager.focusChanged(true, config); assertEquals(1, recaps.size());
	}
	@Test public void logoutFinalizesDropThenClearsEvidence() { boundary(GameState.LOGIN_SCREEN); }
	@Test public void worldHopFinalizesDropThenClearsEvidence() { boundary(GameState.HOPPING); }
	private void boundary(GameState state)
	{
		focus(); drop(); manager.gameStateChanged(state); assertEquals(1, recaps.size());
		manager.loggedIn(Collections.emptyMap(), 99); focus();
		manager.groundQuantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		manager.focusChanged(true, config); assertEquals(1, recaps.size());
	}
	@Test public void shutdownDropsEvidenceWithoutPublishing()
	{
		focus(); drop(); manager.suspend(); manager.loggedIn(Collections.emptyMap(), 99); focus();
		manager.groundQuantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		manager.focusChanged(true, config); assertTrue(recaps.isEmpty());
	}
	@Test public void overlayAndPanelUseSeparateNotableRowsAndOmitEmptySection() throws Exception
	{
		focus(); drop(); manager.groundSpawn(new Object(), ItemID.TRAIL_CLUE_HARD_MAP001, 1, TileItem.OWNERSHIP_SELF, 0, true, config);
		manager.inventoryChanged(Map.of(ItemID.ABYSSAL_WHIP, 1)); AfkRecapSession recap = end();
		AfkRecapItemPresentation presenter = new AfkRecapItemPresentation(id -> new AfkRecapItemPresentation.ItemDetails(
			id == ItemID.ABYSSAL_WHIP ? "Abyssal whip" : "Clue scroll (hard)", id == ItemID.ABYSSAL_WHIP ? 1600000 : 0));
		AfkRecapItemPresentation.Display display = presenter.prepare(recap);
		AfkRecapController overlay = new AfkRecapController(() -> 0L); overlay.show(recap, true, 10, display);
		assertEquals(2, overlay.visiblePresentation(true).getNotableDropRows().size());
		assertEquals(1, overlay.visiblePresentation(true).getItemRows().size());
		assertEquals("1,600,000 gp", display.getTotalValue()); // Drops never inflate inventory value.
		assertTrue(display.getNotableRows().stream().anyMatch(row -> row.getName().equals("Clue scroll (hard)") && row.getValue() == null));
		assertTrue(display.getNotableRows().stream().anyMatch(row -> row.getQuantityAndValue().equals("1  1,600,000 gp")));
		AfkRecapHistory history = new AfkRecapHistory(); history.add(recap);
		SwingUtilities.invokeAndWait(() ->
		{
			AfkRecapPanel panel = new AfkRecapPanel(history, presenter); List<String> labels = new ArrayList<>(); labels(panel, labels);
			assertTrue(labels.contains("Notable drops")); assertTrue(labels.contains("Items gained"));
			assertTrue(labels.contains("Clue scroll (hard)")); assertTrue(labels.contains("1  1,600,000 gp"));
			history.clear();
			AfkRecapSession xpOnly = new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH, 1, Instant.EPOCH,
				600, Map.of(Skill.ATTACK, 1L), Collections.emptySet());
			history.add(xpOnly); panel.refresh(); labels.clear(); labels(panel, labels);
			assertFalse(labels.contains("Notable drops"));
			overlay.show(xpOnly, true, 10, presenter.prepare(xpOnly));
			assertTrue(overlay.visiblePresentation(true).getNotableDropRows().isEmpty());
		});
	}
	@Test(expected = UnsupportedOperationException.class) public void completedDropsAreImmutable()
	{
		focus(); drop(); end().getNotableDrops().put(ItemID.COINS, 1);
	}
	private static void labels(Container container, List<String> result)
	{
		for (Component child : container.getComponents())
		{
			if (child instanceof JLabel) { result.add(((JLabel) child).getText()); }
			if (child instanceof Container) { labels((Container) child, result); }
		}
	}
}

