		Graphics2D graphics = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try { assertNotNull(overlay.render(graphics)); }
		finally { graphics.dispose(); }
		assertEquals(Collections.singletonMap("Genie", 2), controller.visiblePresentation(true).getMissedRandomEvents());
		assertEquals(2, overlay.getPanelComponent().getChildren().stream()
			.filter(component -> component instanceof TitleComponent).count());
		assertEquals(3, overlay.getPanelComponent().getChildren().stream()
			.filter(component -> component instanceof LineComponent).count());
	}

	@Test
	public void emptyMissSectionIsOmittedFromOverlay()
	{
		AfkRecapController controller = new AfkRecapController(() -> 0L);
		AfkRecapSession focus = new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
			2, Instant.EPOCH, 1200, Collections.emptyMap(), Collections.emptySet(),
			Collections.emptyMap(), Collections.emptyMap(), 1);
		controller.show(focus, true, 10);
		AfkRecapOverlay overlay = new AfkRecapOverlay(new AfkRecapPlugin(), new AfkRecapConfig() {}, controller);
		overlay.setClearChildren(false);
		Graphics2D graphics = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try { overlay.render(graphics); }
		finally { graphics.dispose(); }
		assertTrue(controller.visiblePresentation(true).getMissedRandomEvents().isEmpty());
		assertEquals(1, overlay.getPanelComponent().getChildren().stream()
			.filter(component -> component instanceof TitleComponent).count());
	}

	private void labels(Component component, List<String> labels)
	{
		if (component instanceof JLabel) { labels.add(((JLabel) component).getText()); }
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents()) { labels(child, labels); }
		}
	}

	@Test
	public void historyPanelShowsMissNamesAndCounts() throws Exception
	{
		AfkRecapHistory history = new AfkRecapHistory();
		assertTrue(history.add(recap(Collections.singletonMap("Drunken dwarf", 3))));
		List<String> labels = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			AfkRecapPanel panel = new AfkRecapPanel(history, new AfkRecapItemPresentation(id -> null));
			labels(panel, labels);
		});
		assertTrue(labels.contains("Missed random events"));
		assertTrue(labels.contains("Drunken dwarf"));
		assertTrue(labels.contains("3"));
	}

	@Test
	public void emptyMissSectionIsOmittedFromHistoryPanel() throws Exception
	{
		AfkRecapHistory history = new AfkRecapHistory();
		history.add(new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH, 2, Instant.EPOCH,
			1200, Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), Collections.emptyMap(), 1));
		List<String> labels = new ArrayList<>();
		SwingUtilities.invokeAndWait(() -> labels(new AfkRecapPanel(history,
			new AfkRecapItemPresentation(id -> null)), labels));
		assertFalse(labels.contains("Missed random events"));
	}
	@Test
	public void largeOverlayIsBoundedWithoutTruncatingHistoryData()
	{
		Map<String, Integer> misses = new TreeMap<>();
		for (int i = 0; i < 100; i++) { misses.put("Event " + i, 1); }
		AfkRecapSession recap = recap(misses);
		AfkRecapController controller = new AfkRecapController(() -> 0L);
		controller.show(recap, true, 10);
		AfkRecapOverlay overlay = new AfkRecapOverlay(new AfkRecapPlugin(), new AfkRecapConfig() {}, controller);
		overlay.setClearChildren(false);
		Graphics2D graphics = new BufferedImage(400, 600, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try { assertNotNull(overlay.render(graphics)); }
		finally { graphics.dispose(); }
		assertEquals(AfkRecapOverlay.MAX_ROWS, overlay.getPanelComponent().getChildren().size());
		assertEquals(100, recap.getMissedRandomEvents().size());
		AfkRecapHistory history = new AfkRecapHistory();
		assertTrue(history.add(recap));
		assertEquals(100, history.snapshot().get(0).getMissedRandomEvents().size());
	}

}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.*;

public class MissedRandomEventTest
{
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L,
		() -> Instant.EPOCH, recaps::add, Collections::emptyMap);
	private final AfkRecapConfig config = new AfkRecapConfig()
	{
		@Override public int idleGameTicks() { return 1; }
		@Override public boolean idleFishing() { return false; }
		@Override public boolean idleMining() { return false; }
		@Override public boolean idleWoodcutting() { return false; }
		@Override public boolean idleCombat() { return false; }
		@Override public boolean idleSlayer() { return false; }
		@Override public boolean idleSailingSalvaging() { return false; }
		@Override public boolean idleSailingSorting() { return false; }
	};

	private Object targeted(int id, String name)
	{
		Object npc = new Object();
		manager.randomEventTargeted(npc, id, name, true, false);
		return npc;
	}

	private void miss(Object npc)
	{
		manager.randomEventDespawned(npc);
		manager.gameTick(config);
	}

	private AfkRecapSession finish()
	{
		manager.manualInput();
		assertEquals(1, recaps.size());
		return recaps.get(0);
	}

	@Test
	public void localTargetedRandomProducesMissOnlyAfterDespawn()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.gameTick(config);
		assertTrue(recaps.isEmpty());
		miss(npc);
		assertEquals(Collections.singletonMap("Genie", 1), finish().getMissedRandomEvents());
	}

	@Test
	public void anotherPlayersRandomIsIgnored()
	{
		manager.gameTick(config);
		Object npc = new Object();
		manager.randomEventTargeted(npc, NpcID.MACRO_GENI, "Genie", false, false);
		miss(npc);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void nearbyRandomWithoutOwnershipIsIgnored()
	{
		manager.gameTick(config);
		miss(new Object());
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void talkingToOthersRandomCannotCreateOwnership()
	{
		manager.gameTick(config);
		Object npc = new Object();
		manager.randomEventHandled(npc);
		manager.randomEventTargeted(npc, NpcID.MACRO_GENI, "Genie", true, true);
		miss(npc);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void unrelatedNpcTargetingLocalIsIgnored()
	{
		manager.gameTick(config);
		miss(targeted(-1, "Unrelated NPC"));
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void completedInteractionIsHandledAndDoesNotQualifyIdle()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.randomEventHandled(npc); // Local player's InteractingChanged / Talk-to evidence.
		miss(npc);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void dismissedEventIsHandledAndDoesNotQualifyIdle()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_DWARF, "Drunken dwarf");
		manager.randomEventHandled(npc); // Dismiss menu entry for this exact NPC.
		miss(npc);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void duplicateTargetDespawnAndLateSignalsCountOnce()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.randomEventTargeted(npc, NpcID.MACRO_GENI, "Genie", true, false);
		manager.randomEventDespawned(npc);
		manager.randomEventDespawned(npc);
		manager.gameTick(config);
		manager.randomEventTargeted(npc, NpcID.MACRO_GENI, "Genie", true, false);
		miss(npc);
		assertEquals(Collections.singletonMap("Genie", 1), finish().getMissedRandomEvents());
	}

	@Test
	public void repeatedSameTypeAggregatesIncludingUnderwaterVariant()
	{
		manager.gameTick(config);
		miss(targeted(NpcID.MACRO_GENI, "Genie"));
		miss(targeted(NpcID.MACRO_GENI_UNDERWATER, "Genie"));
		assertEquals(Collections.singletonMap("Genie", 2), finish().getMissedRandomEvents());
	}

	@Test
	public void multipleTypesRemainSeparate()
	{
		manager.gameTick(config);
		miss(targeted(NpcID.MACRO_GENI, "Genie"));
		miss(targeted(NpcID.MACRO_DWARF, "Drunken dwarf"));
		Map<String, Integer> expected = new HashMap<>();
		expected.put("Genie", 1);
		expected.put("Drunken dwarf", 1);
		assertEquals(expected, finish().getMissedRandomEvents());
	}

	@Test
	public void missedRandomAloneQualifiesIdleAndKeepsEarlierData()
	{
		manager.baseline(Collections.singletonMap(Skill.SAILING, 1000));
		manager.gameTick(config);
		manager.statChanged(Skill.SAILING, 1050);
		manager.inventoryChanged(Collections.singletonMap(ItemID.COINS, 10));
		miss(targeted(NpcID.MACRO_GENI, "Genie"));
		AfkRecapSession recap = finish();
		assertTrue(recap.isIdleRelevant());
		assertTrue(recap.getRelevantIdleSkills().isEmpty());
		assertEquals(Long.valueOf(50), recap.getXpGained().get(Skill.SAILING));
		assertEquals(Integer.valueOf(10), recap.getItemGains().get(ItemID.COINS));
		assertTrue(new AfkRecapHistory().add(recap));
	}

	@Test
	public void disabledTrackingIgnoresAllSignals()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean trackMissedRandomEvents() { return false; }
			@Override public int idleGameTicks() { return 1; }
		};
		manager.gameTick(disabled);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.randomEventDespawned(npc);
		manager.gameTick(disabled);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void disablingMidSessionClearsEvidenceAndMisses()
	{
		manager.gameTick(config);
		miss(targeted(NpcID.MACRO_GENI, "Genie"));
		Object active = targeted(NpcID.MACRO_DWARF, "Drunken dwarf");
		manager.configureRandomEvents(false);
		manager.randomEventDespawned(active);
		manager.configureRandomEvents(true);
		manager.gameTick(config);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void focusCanRecordMissWithoutAnyXp()
	{
		manager.focusChanged(false, config);
		miss(targeted(NpcID.MACRO_GENI, "Genie"));
		manager.focusChanged(true, config);
		assertEquals(1, recaps.size());
		assertEquals(AfkSessionTrigger.FOCUS, recaps.get(0).getTrigger());
		assertEquals(Collections.singletonMap("Genie", 1), recaps.get(0).getMissedRandomEvents());
	}

	@Test
	public void handledFocusEventDoesNotAddMiss()
	{
		manager.focusChanged(false, config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.randomEventHandled(npc);
		miss(npc);
		manager.focusChanged(true, config);
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void activeAndPendingEventsAreNotMissesOnLogoutDisconnectOrHop()
	{
		for (GameState state : new GameState[] { GameState.LOGIN_SCREEN, GameState.CONNECTION_LOST, GameState.HOPPING })
		{
			for (boolean despawnFirst : new boolean[] { false, true })
			{
				manager.loggedIn(Collections.emptyMap(), 99);
				manager.gameTick(config);
				Object npc = targeted(NpcID.MACRO_GENI, "Genie");
				if (despawnFirst) { manager.randomEventDespawned(npc); }
				manager.gameStateChanged(state);
				manager.randomEventDespawned(npc);
				manager.loggedIn(Collections.emptyMap(), 99);
				manager.gameTick(config);
				manager.randomEventDespawned(npc);
				manager.gameTick(config);
				manager.manualInput();
				assertTrue(recaps.isEmpty());
			}
		}
	}

	@Test
	public void alreadyConfirmedMissSurvivesLogoutFinalization()
	{
		manager.gameTick(config);
		miss(targeted(NpcID.MACRO_GENI, "Genie"));
		manager.gameStateChanged(GameState.CONNECTION_LOST);
		assertEquals(1, recaps.size());
		assertEquals(Collections.singletonMap("Genie", 1), recaps.get(0).getMissedRandomEvents());
	}

	@Test
	public void sessionCompletionAndDiscardClearActiveEvidence()
	{
		manager.gameTick(config);
		Object first = targeted(NpcID.MACRO_GENI, "Genie");
		manager.manualInput(); // Discarded candidate.
		manager.gameTick(config);
		miss(first);
		assertTrue(recaps.isEmpty());
		Object second = targeted(NpcID.MACRO_GENI, "Genie");
		miss(second);
		manager.manualInput();
		manager.gameTick(config);
		miss(second);
		manager.manualInput();
		assertEquals(1, recaps.size());
	}

	@Test
	public void shutdownClearsActiveEvidenceWithoutPublishing()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.suspend();
		manager.randomEventDespawned(npc);
		manager.loggedIn(Collections.emptyMap(), 99);
		manager.gameTick(config);
		miss(npc);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void handlingBeforeDespawnConfirmationSuppressesMiss()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.randomEventDespawned(npc);
		manager.randomEventHandled(npc);
		manager.gameTick(config);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void missDataIsDefensivelyCopiedAndImmutable()
	{
		Map<String, Integer> misses = new HashMap<>();
		misses.put("Genie", 2);
		AfkRecapSession recap = new AfkRecapSession(AfkSessionTrigger.IDLE, 0, Instant.EPOCH,
			1, Instant.EPOCH, 600, Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(),
			Collections.emptyMap(), 0, 0, AfkSessionEndReason.MANUAL_INPUT, Collections.emptyMap(), misses);
		misses.clear();
		assertEquals(Collections.singletonMap("Genie", 2), recap.getMissedRandomEvents());
		try
		{
			recap.getMissedRandomEvents().put("Genie", 10);
			fail("Expected immutable map");
		}
		catch (UnsupportedOperationException expected) { }
	}

	@Test
	public void unconfirmedDespawnAtNormalSessionBoundaryIsOmitted()
	{
		manager.gameTick(config);
		Object npc = targeted(NpcID.MACRO_GENI, "Genie");
		manager.randomEventDespawned(npc);
		manager.manualInput();
		manager.gameTick(config);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void missingNpcOrNameCannotCreateAttributedMiss()
	{
		manager.gameTick(config);
		manager.randomEventTargeted(null, NpcID.MACRO_GENI, "Genie", true, false);
		miss(null);
		miss(targeted(NpcID.MACRO_GENI, null));
		miss(targeted(NpcID.MACRO_GENI, " "));
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void resolvedRandomsLeaveNoStrongEvidenceOrPerTickHistoryScan()
	{
		MissedRandomEventTracker tracker = new MissedRandomEventTracker();
		List<Object> npcs = new ArrayList<>();
		for (int i = 0; i < 1000; i++)
		{
			Object npc = new Object();
			npcs.add(npc); // Keep tombstones alive to exercise late duplicate signals.
			tracker.targeted(npc, NpcID.MACRO_GENI, "Genie", true, false);
			assertEquals(1, tracker.activeEventCount());
			tracker.despawned(npc);
			tracker.gameTick();
			assertEquals(0, tracker.activeEventCount());
		}
		for (Object npc : npcs)
		{
			tracker.targeted(npc, NpcID.MACRO_GENI, "Genie", true, false);
			tracker.despawned(npc);
		}
		tracker.gameTick();
		assertEquals(0, tracker.activeEventCount());
		assertEquals(Collections.singletonMap("Genie", 1000), tracker.misses());
	}

	@Test
	public void trackingIsEnabledByDefault()
	{
		assertTrue(config.trackMissedRandomEvents());
	}
}

package com.afkrecap;

import java.util.Map;
import net.runelite.api.TileItem;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class NotableDropTrackerTest
{
	private final NotableDropTracker tracker = new NotableDropTracker();
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private void spawn(int id, int quantity, int ownership, long price, boolean clue)
	{
		tracker.spawn(new Object(), id, quantity, ownership, price, clue, config);
	}

	@Test public void valuableOwnedDrop() { spawn(ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, 1600000, false); assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 1), tracker.totals()); }
	@Test public void lowValueIgnored() { spawn(ItemID.COINS, 10, TileItem.OWNERSHIP_SELF, 1, false); assertTrue(tracker.totals().isEmpty()); }
	@Test public void thresholdIncludesEntireNewStack() { spawn(ItemID.COINS, 100000, TileItem.OWNERSHIP_SELF, 1, false); assertEquals(Map.of(ItemID.COINS, 100000), tracker.totals()); }
	@Test public void clueBelowThreshold() { spawn(ItemID.TRAIL_CLUE_HARD_MAP001, 1, TileItem.OWNERSHIP_SELF, 0, true); assertEquals(Map.of(ItemID.TRAIL_CLUE_HARD_MAP001, 1), tracker.totals()); }
	@Test public void cluePreferenceDisabled()
	{
		tracker.spawn(new Object(), ItemID.TRAIL_CLUE_HARD_MAP001, 1, TileItem.OWNERSHIP_SELF, 0, true,
			new AfkRecapConfig() { @Override public boolean alwaysTrackClues() { return false; } });
		assertTrue(tracker.totals().isEmpty());
	}
	@Test public void globallyDisabledIncludesClues()
	{
		tracker.spawn(new Object(), ItemID.TRAIL_CLUE_MASTER, 1, TileItem.OWNERSHIP_SELF, 2000000, true,
			new AfkRecapConfig() { @Override public boolean trackNotableDrops() { return false; } });
		assertTrue(tracker.totals().isEmpty());
	}
	@Test public void otherUnownedAndGroupPilesIgnored()
	{
		for (int ownership : new int[]{TileItem.OWNERSHIP_OTHER, TileItem.OWNERSHIP_NONE, TileItem.OWNERSHIP_GROUP})
		{ spawn(ItemID.ABYSSAL_WHIP, 1, ownership, 1600000, false); }
		assertTrue(tracker.totals().isEmpty());
	}
	@Test public void repeatedSameResourceAggregates()
	{
		spawn(ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, 1600000, false);
		spawn(ItemID.ABYSSAL_WHIP, 2, TileItem.OWNERSHIP_SELF, 1600000, false);
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 3), tracker.totals());
	}
	@Test public void multipleTypes()
	{
		spawn(ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, 1600000, false);
		spawn(ItemID.TRAIL_CLUE_BEGINNER, 1, TileItem.OWNERSHIP_SELF, 0, true);
		assertEquals(2, tracker.totals().size());
	}
	@Test public void duplicateSpawnAndQuantityChangeCountOnce()
	{
		Object pile = new Object();
		tracker.spawn(pile, ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		tracker.spawn(pile, ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		tracker.quantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		tracker.quantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 2), tracker.totals());
	}
	@Test public void pickupDecreaseDoesNotSubtractAndDespawnRetainsTotals()
	{
		Object pile = new Object();
		tracker.spawn(pile, ItemID.ABYSSAL_WHIP, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		tracker.quantityChanged(pile, ItemID.ABYSSAL_WHIP, 2, 1, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		tracker.despawn(pile);
		tracker.quantityChanged(pile, ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		assertEquals(Map.of(ItemID.ABYSSAL_WHIP, 2), tracker.totals());
	}
	@Test public void preSessionPileAdditionIgnored()
	{
		tracker.quantityChanged(new Object(), ItemID.ABYSSAL_WHIP, 1, 2, TileItem.OWNERSHIP_SELF, 1600000, false, config);
		assertTrue(tracker.totals().isEmpty());
	}
	@Test public void stackAdditionThresholdUsesAddedQuantity()
	{
		Object pile = new Object();
		tracker.spawn(pile, ItemID.COINS, 90000, TileItem.OWNERSHIP_SELF, 1, false, config);
		tracker.quantityChanged(pile, ItemID.COINS, 90000, 110000, TileItem.OWNERSHIP_SELF, 1, false, config);
		assertTrue(tracker.totals().isEmpty());
		tracker.quantityChanged(pile, ItemID.COINS, 110000, 210000, TileItem.OWNERSHIP_SELF, 1, false, config);
		assertEquals(Map.of(ItemID.COINS, 100000), tracker.totals());
	}
	@Test public void valueAndQuantityOverflowAreSafe()
	{
		spawn(ItemID.ABYSSAL_WHIP, Integer.MAX_VALUE, TileItem.OWNERSHIP_SELF, Long.MAX_VALUE, false);
		spawn(ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, Long.MAX_VALUE, false);
		assertEquals(Integer.valueOf(Integer.MAX_VALUE), tracker.totals().get(ItemID.ABYSSAL_WHIP));
	}
	@Test public void failedPriceStillAllowsConfirmedClue()
	{
		spawn(ItemID.TRAIL_CLUE_MASTER, 1, TileItem.OWNERSHIP_SELF, -1, true);
		spawn(ItemID.ABYSSAL_WHIP, 1, TileItem.OWNERSHIP_SELF, -1, false);
		assertEquals(Map.of(ItemID.TRAIL_CLUE_MASTER, 1), tracker.totals());
	}
	@Test public void supportedClueVariantsUseItemParameterOrKnownBaseId()
	{
		assertTrue(ClueDropItems.isClue(ItemID.TRAIL_CLUE_BEGINNER, -1));
		assertTrue(ClueDropItems.isClue(ItemID.TRAIL_CLUE_MASTER, -1));
		for (int id : new int[]{ItemID.TRAIL_CLUE_EASY_SIMPLE001, ItemID.TRAIL_CLUE_EASY_SIMPLE002,
			ItemID.TRAIL_CLUE_MEDIUM_SEXTANT001, ItemID.TRAIL_CLUE_HARD_MAP001, ItemID.TRAIL_CLUE_HARD_SEXTANT001,
			ItemID.TRAIL_CLUE_ELITE_MUSIC001, ItemID.TRAIL_CLUE_ELITE_MUSIC002})
		{ assertTrue(ClueDropItems.isClue(id, 1)); }
		assertFalse(ClueDropItems.isClue(ItemID.ABYSSAL_WHIP, -1));
		assertFalse(ClueDropItems.isClue(ItemID.TRAIL_CLUE_HARD_SEXTANT001_CASKET, -1));
	}
}

package com.afkrecap;

import java.util.Collections;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static com.afkrecap.ResourceAcquisitionMessages.Family.*;
import static org.junit.Assert.*;

public class ResourceAcquisitionTrackerTest
{
	private final ResourceAcquisitionTracker tracker = new ResourceAcquisitionTracker(Collections.emptyMap());
	private void fish() { tracker.message("You catch a trout.", true, false); }
	private void log() { tracker.message("You get some oak logs.", false, true); }
	private void inventory(int id, int count) { tracker.inventoryChanged(Collections.singletonMap(id, count)); }
	private void total(int id, int count) { assertEquals(Collections.singletonMap(id, count), tracker.gains()); }
	private void settle() { tracker.gameTick(); tracker.gameTick(); }

	@Test public void normalFish() { inventory(ItemID.RAW_TROUT, 1); total(ItemID.RAW_TROUT, 1); }
	@Test public void hiddenFish() { fish(); total(ItemID.RAW_TROUT, 1); }
	@Test public void normalLog() { inventory(ItemID.OAK_LOGS, 1); total(ItemID.OAK_LOGS, 1); }
	@Test public void hiddenLog() { log(); total(ItemID.OAK_LOGS, 1); }
	@Test public void fishMessageAndInventoryCountOnce() { fish(); inventory(ItemID.RAW_TROUT, 1); total(ItemID.RAW_TROUT, 1); }
	@Test public void logInventoryAndMessageCountOnce() { inventory(ItemID.OAK_LOGS, 1); log(); total(ItemID.OAK_LOGS, 1); }
	@Test public void multipleFishWithPartialInventory() { fish(); fish(); fish(); inventory(ItemID.RAW_TROUT, 2); total(ItemID.RAW_TROUT, 3); }
	@Test public void multipleLogsWithPartialInventory() { log(); log(); inventory(ItemID.OAK_LOGS, 1); total(ItemID.OAK_LOGS, 2); }
	@Test public void differentResourcesNeverMatch()
	{
		fish(); inventory(ItemID.RAW_SALMON, 1);
		assertEquals(Map.of(ItemID.RAW_TROUT, 1, ItemID.RAW_SALMON, 1), tracker.gains());
	}
	@Test public void inventoryArrivingNextTickMatches() { fish(); tracker.gameTick(); inventory(ItemID.RAW_TROUT, 1); settle(); total(ItemID.RAW_TROUT, 1); }
	@Test public void messageArrivingNextTickMatches() { inventory(ItemID.OAK_LOGS, 1); tracker.gameTick(); log(); settle(); total(ItemID.OAK_LOGS, 1); }
	@Test public void inventoryThenAutomaticStorageCountsOnce()
	{
		fish(); inventory(ItemID.RAW_TROUT, 1); tracker.inventoryChanged(Collections.emptyMap());
		total(ItemID.RAW_TROUT, 1);
	}
	@Test public void emptyFishBarrelDoesNotCountAgain()
	{
		fish(); settle(); tracker.transfer(FISH); inventory(ItemID.RAW_TROUT, 1); total(ItemID.RAW_TROUT, 1);
	}
	@Test public void emptyLogBasketDoesNotCountAgain()
	{
		log(); settle(); tracker.transfer(LOG); inventory(ItemID.OAK_LOGS, 1); total(ItemID.OAK_LOGS, 1);
	}
	@Test public void delayedEmptyConfirmationRemovesUncertainInventory()
	{
		inventory(ItemID.OAK_LOGS, 20); tracker.gameTick(); tracker.transfer(LOG); assertTrue(tracker.gains().isEmpty());
	}
	@Test public void fillFromExistingInventoryIsNotAcquisition()
	{
		ResourceAcquisitionTracker existing = new ResourceAcquisitionTracker(Map.of(ItemID.RAW_TROUT, 20));
		existing.transfer(FISH); existing.inventoryChanged(Collections.emptyMap()); assertTrue(existing.gains().isEmpty());
	}
	@Test public void fillPreservesConfirmedAcquisition()
	{
		fish(); inventory(ItemID.RAW_TROUT, 1); tracker.transfer(FISH); tracker.inventoryChanged(Collections.emptyMap()); total(ItemID.RAW_TROUT, 1);
	}
	@Test public void delayedFillPreservesAlreadyReconciledAcquisitions()
	{
		fish(); tracker.gameTick(); inventory(ItemID.RAW_TROUT, 1); tracker.gameTick();
		tracker.transfer(FISH); tracker.inventoryChanged(Collections.emptyMap()); total(ItemID.RAW_TROUT, 1);
	}

	@Test public void transferWindowExpires()
	{
		tracker.transfer(LOG); settle(); tracker.gameTick(); inventory(ItemID.OAK_LOGS, 1); total(ItemID.OAK_LOGS, 1);
	}
	@Test public void transferDoesNotSuppressOtherFamily() { tracker.transfer(FISH); inventory(ItemID.OAK_LOGS, 1); total(ItemID.OAK_LOGS, 1); }
	@Test public void ambiguousAndCheckMessagesIgnored()
	{
		for (String message : new String[]{"You catch a fish.", "You catch something.", "You get some wood.",
			"The basket contains 20 oak logs.", "You empty your basket.", "You catch 2 trout.", "You catch a sacred eel."})
		{ tracker.message(message, true, true); }
		assertTrue(tracker.gains().isEmpty());
	}
	@Test public void closedStorageDoesNotSupplyMessageEvidence()
	{
		tracker.message("You catch a trout.", false, false); tracker.message("You get some oak logs.", false, false);
		assertTrue(tracker.gains().isEmpty());
	}
	@Test public void typedFishBonusCountsExtra()
	{
		fish(); tracker.message("Rada's blessing enabled you to catch an extra fish.", true, false); total(ItemID.RAW_TROUT, 2);
	}
	@Test public void typedLogBonusReconcilesWithInventory()
	{
		log(); tracker.message("Your Kandarin headgear provides you with an additional log.", false, true);
		inventory(ItemID.OAK_LOGS, 2); total(ItemID.OAK_LOGS, 2);
	}
	@Test public void secondSupportedBonuses()
	{
		fish(); tracker.message("The spirit flakes enabled you to catch an extra fish.", true, false);
		log(); tracker.message("The nature offerings enabled you to chop an extra log.", false, true);
		assertEquals(Map.of(ItemID.RAW_TROUT, 2, ItemID.OAK_LOGS, 2), tracker.gains());
	}
	@Test public void bonusWithoutTypedContextIgnored()
	{
		tracker.message("Rada's blessing enabled you to catch an extra fish.", true, false); assertTrue(tracker.gains().isEmpty());
	}
	@Test public void bonusAfterTickOrAmbiguityIgnored()
	{
		fish(); tracker.gameTick(); tracker.message("Rada's blessing enabled you to catch an extra fish.", true, false);
		fish(); tracker.message("You catch something.", true, false);
		tracker.message("The spirit flakes enabled you to catch an extra fish.", true, false); total(ItemID.RAW_TROUT, 2);
	}
	@Test public void bonusWrongFamilyAndDuplicateIgnored()
	{
		fish(); tracker.message("Your Kandarin headgear provides you with an additional log.", true, true);
		tracker.message("Rada's blessing enabled you to catch an extra fish.", true, false);
		tracker.message("Rada's blessing enabled you to catch an extra fish.", true, false); total(ItemID.RAW_TROUT, 2);
	}
	@Test public void unrelatedItemsRemainNormal() { inventory(ItemID.COINS, 200); total(ItemID.COINS, 200); }
	@Test public void cheapChatPrefilterPreservesAllSupportedAcquisitionsAndBonuses()
	{
		for (String message : new String[]{"You catch a trout.", "You get some oak logs.",
			"You get an arctic pine log.", "Rada's blessing enabled you to catch an extra fish.",
			"The spirit flakes enabled you to catch an extra fish.",
			"Your Kandarin headgear provides you with an additional log.",
			"The nature offerings enabled you to chop an extra log."})
		{
			assertTrue(ResourceAcquisitionMessages.mayAcquire(message));
		}
		assertFalse(ResourceAcquisitionMessages.mayAcquire(null));
		assertFalse(ResourceAcquisitionMessages.mayAcquire("The basket contains 20 oak logs."));
		assertFalse(ResourceAcquisitionMessages.mayAcquire("You empty your basket."));
	}

	@Test public void unrelatedChatStillInvalidatesBonusEvidence()
	{
		log(); tracker.message("The basket contains 20 oak logs.", false, false);
		tracker.message("Your Kandarin headgear provides you with an additional log.", false, true);
		total(ItemID.OAK_LOGS, 1);
	}

	@Test public void unmatchedMessagesDoNotRemainPendingAcrossManyTicks()
	{
		for (int i = 0; i < 1000; i++) { log(); tracker.gameTick(); }
		settle(); inventory(ItemID.OAK_LOGS, 1);
		total(ItemID.OAK_LOGS, 1001);
	}

}

package com.afkrecap;

import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class ResourceContainerStateTest
{
	@Test public void bothOpenFishContainersEnableEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.FISH_BARREL_OPEN)).hiddenFish());
		assertTrue(new ResourceContainerState(Set.of(ItemID.FISH_SACK_BARREL_OPEN)).hiddenFish());
	}
	@Test public void bothOpenLogContainersEnableEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN)).hiddenLogs());
		assertTrue(new ResourceContainerState(Set.of(ItemID.FORESTRY_BASKET_OPEN)).hiddenLogs());
	}
	@Test public void closedContainersDoNotEnableEvidence()
	{
		ResourceContainerState state = new ResourceContainerState(Set.of(ItemID.FISH_BARREL_CLOSED,
			ItemID.FISH_SACK_BARREL_CLOSED, ItemID.LOG_BASKET_CLOSED, ItemID.FORESTRY_BASKET_CLOSED));
		assertFalse(state.hiddenFish()); assertFalse(state.hiddenLogs());
	}
	@Test public void consumingToolsDisableUncertainHiddenGains()
	{
		assertFalse(new ResourceContainerState(Set.of(ItemID.FISH_BARREL_OPEN, ItemID.INFERNAL_HARPOON)).hiddenFish());
		assertFalse(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN, ItemID.INFERNAL_AXE)).hiddenLogs());
	}
	@Test public void fellingAxesAllowConfirmedLogEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN, ItemID.RUNE_AXE_2H)).hiddenLogs());
		assertTrue(new ResourceContainerState(Set.of(ItemID.FORESTRY_BASKET_OPEN, ItemID.DRAGON_AXE_2H)).hiddenLogs());
	}

	@Test public void transferDetectionIncludesClosedContainersButNotOrdinaryItems()
	{
		ResourceContainerState state = new ResourceContainerState(Set.of(ItemID.FISH_BARREL_CLOSED));
		assertTrue(state.hasContainer(ResourceAcquisitionMessages.Family.FISH));
		assertFalse(state.hasContainer(ResourceAcquisitionMessages.Family.LOG));
		assertFalse(new ResourceContainerState(Set.of(ItemID.OAK_LOGS)).hasContainer(ResourceAcquisitionMessages.Family.LOG));
	}

	@Test public void depletedInfernalToolsAllowEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.FISH_BARREL_OPEN, ItemID.INFERNAL_HARPOON_EMPTY)).hiddenFish());
		assertTrue(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN, ItemID.INFERNAL_AXE_EMPTY)).hiddenLogs());
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class SailingIdleActivityTest
{
	private AfkRecapConfig config(boolean salvaging, boolean sorting)
	{
		return new AfkRecapConfig()
		{
			@Override public boolean idleSailingSalvaging() { return salvaging; }
			@Override public boolean idleSailingSorting() { return sorting; }
		};
	}

	private AfkSessionManager candidate(AfkRecapConfig config, List<AfkRecapSession> recaps)
	{
		AfkSessionManager manager = new AfkSessionManager(() -> 0L, () -> Instant.EPOCH,
			recaps::add, Collections::emptyMap);
		manager.baseline(Collections.singletonMap(Skill.SAILING, 1000));
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(config);
		}
		return manager;
	}

	private void combination(boolean salvaging, boolean sorting)
	{
		AfkRecapConfig config = config(salvaging, sorting);
		for (IdleActivity signal : new IdleActivity[] {
			SailingActivitySignals.animation(AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_IDLE01),
			SailingActivitySignals.animation(AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_INTERACT01),
			SailingActivitySignals.message("You sort through the small salvage and find some loot.") })
		{
			List<AfkRecapSession> recaps = new ArrayList<>();
			AfkSessionManager manager = candidate(config, recaps);
			manager.inventoryChanged(Collections.singletonMap(ItemID.COINS, 20));
			manager.statChanged(Skill.SAILING, 1050);
			assertTrue("Generic Sailing XP cannot identify an activity", manager.relevantSkills().isEmpty());
			manager.activityDetected(signal);
			boolean enabled = signal == IdleActivity.SAILING_SALVAGING ? salvaging : sorting;
			assertEquals(enabled, manager.relevantSkills().contains(Skill.SAILING));
			manager.manualInput();
			assertEquals(enabled ? 1 : 0, recaps.size());
			if (enabled)
			{
				assertEquals(Collections.singletonMap(Skill.SAILING, 50L), recaps.get(0).getXpGained());
				assertEquals(Collections.singletonMap(ItemID.COINS, 20), recaps.get(0).getItemGains());
			}
		}
	}

	@Test public void salvagingOnly() { combination(true, false); }
	@Test public void sortingOnly() { combination(false, true); }
	@Test public void bothEnabled() { combination(true, true); }
	@Test public void bothDisabled() { combination(false, false); }

	@Test
	public void genericSailingXpAloneNeverQualifies()
	{
		for (boolean salvaging : new boolean[] { false, true })
		{
			for (boolean sorting : new boolean[] { false, true })
			{
				List<AfkRecapSession> recaps = new ArrayList<>();
				AfkSessionManager manager = candidate(config(salvaging, sorting), recaps);
				manager.statChanged(Skill.SAILING, 1050);
				manager.manualInput();
				assertTrue(recaps.isEmpty());
			}
		}
	}

	@Test
	public void disabledSailingXpStillAppearsInAnotherRelevantIdleRecap()
	{
		List<AfkRecapSession> recaps = new ArrayList<>();
		AfkSessionManager manager = candidate(config(false, false), recaps);
		manager.statChanged(Skill.SAILING, 1050);
		manager.statChanged(Skill.MINING, 1000); // Baseline, not an acquisition.
		manager.statChanged(Skill.MINING, 1010);
		manager.manualInput();
		assertEquals(1, recaps.size());
		assertEquals(Long.valueOf(50), recaps.get(0).getXpGained().get(Skill.SAILING));
		assertEquals(Collections.singleton(Skill.MINING), recaps.get(0).getRelevantIdleSkills());
	}

	@Test
	public void verifiedGatheringAnimationsAreDistinctFromSorting()
	{
		for (int animation : new int[] {
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_IDLE01,
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_2X5_IDLE01,
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_3X8_IDLE01,
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_SALVAGING01 })
		{
			assertEquals(IdleActivity.SAILING_SALVAGING, SailingActivitySignals.animation(animation));
		}
		assertEquals(IdleActivity.SAILING_SORTING,
			SailingActivitySignals.animation(AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_INTERACT01));
		assertNull(SailingActivitySignals.animation(-1));
		assertNull(SailingActivitySignals.animation(AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_RESET01));
		assertNull(SailingActivitySignals.animation(AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_DROP01_CREW));
	}

	@Test
	public void sortingMessagesUseRuneLiteLootTrackerPattern()
	{
		for (String tier : new String[] { "small", "fishy", "barracuda", "large", "plundered", "martial", "fremennik", "opulent" })
		{
			assertEquals(IdleActivity.SAILING_SORTING,
				SailingActivitySignals.message("You sort through the " + tier + " salvage and find some loot."));
		}
		assertNull(SailingActivitySignals.message(null));
		assertNull(SailingActivitySignals.message("You gain some Sailing experience."));
		assertNull(SailingActivitySignals.message("You gather some small salvage."));
	}

	@Test
	public void focusCollectsSailingWithEveryToggleCombination()
	{
		for (boolean salvaging : new boolean[] { false, true })
		{
			for (boolean sorting : new boolean[] { false, true })
			{
				AfkRecapConfig config = config(salvaging, sorting);
				List<AfkRecapSession> recaps = new ArrayList<>();
				AfkSessionManager manager = new AfkSessionManager(() -> 0L, () -> Instant.EPOCH, recaps::add);
				manager.baseline(Collections.singletonMap(Skill.SAILING, 1000));
				manager.focusChanged(false, config);
				manager.activityDetected(IdleActivity.SAILING_SALVAGING);
				manager.activityDetected(IdleActivity.SAILING_SORTING);
				manager.statChanged(Skill.SAILING, 1050);
				manager.focusChanged(true, config);
				assertEquals(1, recaps.size());
				assertTrue(recaps.get(0).getRelevantIdleSkills().isEmpty());
				assertEquals(Long.valueOf(50), recaps.get(0).getXpGained().get(Skill.SAILING));
			}
		}
	}

	@Test
	public void activitySignalsDoNotLeakAcrossCandidatesOrLogout()
	{
		List<AfkRecapSession> recaps = new ArrayList<>();
		AfkRecapConfig config = config(true, false);
		AfkSessionManager manager = candidate(config, recaps);
		manager.activityDetected(IdleActivity.SAILING_SALVAGING);
		manager.statChanged(Skill.SAILING, 1050);
		manager.gameStateChanged(GameState.LOGIN_SCREEN);
		assertEquals(1, recaps.size());
		manager.activityDetected(IdleActivity.SAILING_SALVAGING);
		manager.loggedIn(Collections.singletonMap(Skill.SAILING, 1050), 99);
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		manager.statChanged(Skill.SAILING, 1100);
		manager.manualInput();
		assertEquals(1, recaps.size());
	}

	@Test
	public void defaultsPreserveSalvagingAndOptOutOfSorting()
	{
		AfkRecapConfig defaults = new AfkRecapConfig() {};
		assertTrue(defaults.idleSailingSalvaging());
		assertFalse(defaults.idleSailingSorting());
		assertFalse(IdleActivity.enabledSkills(defaults).contains(Skill.SAILING));
	}
}
